private fun EventRaceData.containsReadoutForSiNumber(siNumber: Int): Boolean =
    competitorData.any { it.readoutData?.result?.siNumber == siNumber } ||
        unmatchedReadoutData.any { it.result.siNumber == siNumber }

/**
 * Returns every category-like container that can hold protected course data.
 *
 * Active categories drive competitor operations. Inactive course mappings exist only because a
 * route import can arrive before start-list/category data; Course Analyzer still needs to see
 * those imported routes, while active categories with the same normalized name remain authoritative.
 */
internal fun protectedCourseStateCategories(raceData: EventRaceData): List<EventCategoryData> {
    val activeNames = raceData.categories.mapTo(mutableSetOf()) { categoryData ->
        categoryData.category.name.protectedCourseStateCategoryMatchText()
    }
    return raceData.categories + raceData.courseMappings.filterNot { mapping ->
        mapping.category.name.protectedCourseStateCategoryMatchText() in activeNames
    }
}

/** Returns every stored container that may hold encrypted course data, including name-overlapping mappings. */
internal fun protectedCourseDataContainers(raceData: EventRaceData): List<EventCategoryData> =
    org.openardf.radiooracle.shared.event.EventCourseDrafts.protectedCategories(raceData)

/** Normalizes names for matching active categories to their inactive course-mapping counterparts. */
private fun String.protectedCourseStateCategoryMatchText(): String =
    StandardCategoryRules.normalizedCategoryName(this).uppercase()

internal data class DesktopProtectedCourseState(
    val protectedIdealOrderByCategoryId: Map<String, String>,
    val protectedCourseInfoByCategoryId: Map<String, ProtectedCourseInfo>
)

internal data class DesktopCoursePasswordUpdate(
    val projectFile: EventProjectFile,
    val password: String?,
    val courseState: DesktopProtectedCourseState,
    val replacedExistingPassword: Boolean,
    val removedPassword: Boolean = false
)

internal fun updatedCoursePassword(
    projectFile: EventProjectFile,
    oldPassword: String,
    newPassword: String,
    confirmPassword: String
): DesktopCoursePasswordUpdate {
    val trimmedOldPassword = oldPassword.trim()
    val trimmedNewPassword = newPassword.trim()
    if (trimmedNewPassword.isEmpty() && confirmPassword.isBlank()) {
        val removal = removedCourseEncryption(projectFile, trimmedOldPassword)
        return DesktopCoursePasswordUpdate(
            projectFile = removal.projectFile,
            password = null,
            courseState = removal.courseState,
            replacedExistingPassword = false,
            removedPassword = true
        )
    }
    require(trimmedNewPassword.isNotEmpty()) { "New Race Password cannot be blank." }
    require(trimmedNewPassword == confirmPassword.trim()) { "New Race Passwords do not match." }
    val hasEncryptedCourseProtection = projectFile.hasEncryptedCategoryData()
    require(!hasEncryptedCourseProtection || trimmedOldPassword.isNotEmpty()) {
        "Current Race Password cannot be blank."
    }
    val updatedProject = when {
        hasEncryptedCourseProtection -> DesktopProtectedCourseOrder.reencryptProjectCourseProtection(
            projectFile,
            oldPassword = trimmedOldPassword,
            newPassword = trimmedNewPassword
        )
        projectFile.hasUnencryptedCategoryData() ->
            DesktopProtectedCourseOrder.protectProjectCourseData(projectFile, trimmedNewPassword)
        else -> projectFile.copy(
            raceData = projectFile.raceData.copy(
                categories = projectFile.raceData.categories.map { categoryData ->
                    categoryData.copy(
                        category = categoryData.category.copy(
                            encryptedIdealOrder = DesktopProtectedCourseOrder.encrypt("", trimmedNewPassword)
                        )
                    )
                }
            )
        )
    }
    return DesktopCoursePasswordUpdate(
        projectFile = updatedProject,
        password = trimmedNewPassword,
        courseState = decryptedProtectedCourseState(updatedProject, trimmedNewPassword),
        replacedExistingPassword = hasEncryptedCourseProtection
    )
}

internal data class DesktopCourseProtectionRemoval(
    val projectFile: EventProjectFile,
    val courseState: DesktopProtectedCourseState
)

internal fun removedCourseEncryption(
    projectFile: EventProjectFile,
    password: String
): DesktopCourseProtectionRemoval {
    val updatedProject = DesktopProtectedCourseOrder.removeProjectCourseProtection(projectFile, password)
    return DesktopCourseProtectionRemoval(
        projectFile = updatedProject,
        courseState = decryptedProtectedCourseState(updatedProject, "")
    )
}

/**
 * Testable decryption hook for the protected route state that the desktop UI keeps in memory.
 *
 * This is intentionally shared by normal imports and duplicate-import refreshes: an identical
 * import does not rewrite the Race File, but it may be the first time in this session that the
 * user supplied the password needed to make already-stored routes visible to Course Analyzer.
 */
internal fun decryptedProtectedCourseState(
    projectFile: EventProjectFile,
    password: String
): DesktopProtectedCourseState {
    val courseCategories = projectFile.raceData.categories + projectFile.raceData.courseMappings
    return DesktopProtectedCourseState(
        protectedIdealOrderByCategoryId = courseCategories.associate { categoryData ->
            categoryData.category.id to categoryData.category.storedIdealOrder(password)
        },
        protectedCourseInfoByCategoryId = courseCategories.mapNotNull { categoryData ->
            val category = categoryData.category
            val courseInfo = category.storedCourseInfo(password)
            courseInfo?.let { category.id to it }
        }.toMap()
    )
}

internal fun publicResultsNeedCourseUnlock(
    projectFiles: List<EventProjectFile>,
    isProtectedCourseOrderUnlocked: Boolean
): Boolean =
    !isProtectedCourseOrderUnlocked && projectFiles.any { projectFile ->
        EventResultDetails.from(projectFile.raceData).isNotEmpty() && projectFile.hasEncryptedCategoryData()
    }

internal fun protectedCourseInfoForResultCategory(
    projectFile: EventProjectFile,
    protectedCourseInfoByCategoryId: Map<String, ProtectedCourseInfo>,
    resultCategoryId: String,
    resultCategoryName: String
): ProtectedCourseInfo? {
    protectedCourseInfoByCategoryId[resultCategoryId]?.let { return it }
    val matches = (projectFile.raceData.categories + projectFile.raceData.courseMappings)
        .filter { StandardCategoryRules.categoryNamesEquivalent(it.category.name, resultCategoryName) }
        .mapNotNull { protectedCourseInfoByCategoryId[it.category.id] }.distinct()
    require(matches.size <= 1) { "Multiple different stored courses match $resultCategoryName. Review its course mapping before exporting." }
    return matches.singleOrNull()
}

internal fun decryptedPublicResultsCourseState(
    projectFiles: List<EventProjectFile>,
    currentProject: EventProjectFile,
    password: String
): DesktopProtectedCourseState {
    val trimmedPassword = password.trim()
    val allProjects = (projectFiles + currentProject).distinct()
    require(allProjects.none(EventProjectFile::hasEncryptedCategoryData) || trimmedPassword.isNotEmpty()) {
        "Race Password cannot be blank."
    }
    allProjects
        .filter(EventProjectFile::hasEncryptedCategoryData)
        .forEach { project -> decryptedProtectedCourseState(project, trimmedPassword) }
    return decryptedProtectedCourseState(currentProject, trimmedPassword)
}

internal fun loadPublicResultSeriesRaces(
    manifestPath: Path,
    currentPath: Path?,
    currentProject: EventProjectFile?,
    protectedCoursePassword: String?,
    currentProtectedCourseInfoByCategoryId: Map<String, ProtectedCourseInfo>,
    awardDisplayMode: EventAwardDisplayMode,
    includeCourseDiagrams: Boolean? = null
): Pair<String, List<DesktopPublicResultSeriesRace>> {
    val seriesFile = DesktopEventSeriesFiles.read(manifestPath)
    val seriesFolder = requireNotNull(manifestPath.parent) {
        "Race Series manifest has no parent folder."
    }
    val normalizedCurrentPath = currentPath?.toAbsolutePath()?.normalize()
    val races = seriesFile.sortedEvents().map { event ->
        val eventPath = seriesFolder.resolve(event.eventFilePath).normalize()
        require(DesktopEventSeriesFiles.exists(eventPath)) {
            "Series member ${event.displayName} is missing. Restore it or update series membership before publishing."
        }
        val isCurrentEvent = eventPath.toAbsolutePath().normalize() == normalizedCurrentPath
        val project = if (isCurrentEvent) {
            currentProject ?: DesktopEventSeriesFiles.readEvent(eventPath)
        } else {
            DesktopEventSeriesFiles.readEvent(eventPath)
        }
        val hasAppliedCourses = (project.raceData.categories + project.raceData.courseMappings).any {
            it.category.courseInfo != null || !it.category.encryptedCourseInfo.isNullOrBlank()
        }
        val wantsCourses = includeCourseDiagrams == true && hasAppliedCourses
        val courseInfo = when {
            includeCourseDiagrams == false -> emptyMap()
            wantsCourses -> decryptedProtectedCourseState(project, protectedCoursePassword.orEmpty()).protectedCourseInfoByCategoryId
            isCurrentEvent && currentProtectedCourseInfoByCategoryId.isNotEmpty() ->
                currentProtectedCourseInfoByCategoryId
            project.hasUnencryptedCategoryData() && !project.hasEncryptedCategoryData() ->
                decryptedProtectedCourseState(project, "").protectedCourseInfoByCategoryId
            protectedCoursePassword != null -> runCatching {
                decryptedProtectedCourseState(project, protectedCoursePassword).protectedCourseInfoByCategoryId
            }.getOrElse { emptyMap() }
            else -> emptyMap()
        }
        DesktopPublicResultSeriesRace(project, courseInfo, awardDisplayMode, includeCourseDiagrams = if (includeCourseDiagrams == null) courseInfo.isNotEmpty() else wantsCourses)
    }
    return seriesFile.name to races
}

internal fun savedPublicResultsPublication(
    manifestPath: Path?,
    currentProject: EventProjectFile?
): PublicResultsPublication? =
    manifestPath
        ?.let(DesktopEventSeriesFiles::read)
        ?.publicResultsPublication
        ?: currentProject?.publicResultsPublication

internal fun configuredPublicResultsUrl(
    settings: DesktopCloudflarePagesPublishSettings,
    currentProject: EventProjectFile?,
    seriesFile: EventSeriesFile?,
    generatedAt: java.time.Instant = java.time.Instant.now()
): String? {
    if (!settings.isComplete() || currentProject == null) {
        return null
    }
    val publicPath = if (seriesFile == null) {
        DesktopPublicResultSiteExports.eventPath(currentProject, generatedAt)
    } else {
        val firstEvent = seriesFile.sortedEvents().firstOrNull() ?: return null
        DesktopPublicResultSiteExports.seriesPath(
            seriesName = seriesFile.name,
            firstStartDateTimeIso = firstEvent.startDateTimeIso,
            generatedAt = generatedAt
        )
    }
    return publicResultsUrl(settings, publicPath)
}

internal data class DesktopPublicResultsUrlState(
    val savedUrl: String?,
    val configuredUrl: String?
)

internal fun loadPublicResultsUrlState(
    currentPath: Path?,
    currentProject: EventProjectFile?,
    settings: DesktopCloudflarePagesPublishSettings,
    store: EventSeriesStore = DesktopEventSeriesFiles,
    generatedAt: java.time.Instant = java.time.Instant.now()
): DesktopPublicResultsUrlState {
    val seriesFile = runCatching {
        currentPath
            ?.let { eventPath ->
                DesktopEventSeriesActions.findManifestNearEvent(
                    eventPath = eventPath,
                    seriesLink = currentProject?.seriesLink,
                    store = store
                )
            }
            ?.let(store::read)
    }.getOrNull()
    return DesktopPublicResultsUrlState(
        savedUrl = (seriesFile?.publicResultsPublication ?: currentProject?.publicResultsPublication)?.url,
        configuredUrl = configuredPublicResultsUrl(
            settings = settings,
            currentProject = currentProject,
            seriesFile = seriesFile,
            generatedAt = generatedAt
        )
    )
}

@Composable
private fun rememberDesktopPublicResultsUrlState(
    currentPath: Path?,
    currentProject: EventProjectFile?,
    settings: DesktopCloudflarePagesPublishSettings,
    seriesRevision: List<DesktopEventSeriesEventSummary>
): DesktopPublicResultsUrlState {
    val race = currentProject?.raceData?.race
    var urlState by remember(
        race?.id,
        race?.name,
        race?.startDateTimeIso,
        currentProject?.seriesLink,
        currentPath,
        settings,
        seriesRevision
    ) {
        mutableStateOf(DesktopPublicResultsUrlState(savedUrl = null, configuredUrl = null))
    }
    LaunchedEffect(
        race?.id,
        race?.name,
        race?.startDateTimeIso,
        currentProject?.seriesLink,
        currentPath,
        settings,
        seriesRevision
    ) {
        urlState = withContext(Dispatchers.IO) {
            loadPublicResultsUrlState(
                currentPath = currentPath,
                currentProject = currentProject,
                settings = settings
            )
        }
    }
    return urlState
}

internal fun publicResultsUrl(
    settings: DesktopCloudflarePagesPublishSettings,
    publicPath: String
): String? =
    settings
        .takeIf(DesktopCloudflarePagesPublishSettings::isComplete)
        ?.let {
            DesktopCloudflarePagesPublisher.publicResultsUrl(
                it.publicSiteBaseUrl(),
                publicPath
            )
        }

internal fun persistPublicResultsPublication(
    manifestPath: Path?,
    projectSession: DesktopProjectSession,
    publication: PublicResultsPublication
): EventProjectFile? {
    if (manifestPath != null) {
        val seriesFile = DesktopEventSeriesFiles.read(manifestPath)
        DesktopEventSeriesFiles.write(
            manifestPath,
            seriesFile.copy(publicResultsPublication = publication)
        )
        return null
    }
    val updatedProject = projectSession.updateCurrentProject { currentProject ->
        currentProject.copy(publicResultsPublication = publication)
    }
    if (projectSession.currentPath != null) {
        projectSession.save()
    }
    return updatedProject
}

