        fun startContinuousSportIdentReadout() {
            if (isDownloadingSiReadout || isContinuousSiReadoutActive || isReadingCompetitorSiCard) {
                return
            }
            val currentProject = projectSession.currentProject
            if (currentProject == null) {
                projectStatusText = "Open or create a Race File before downloading SI cards."
                DesktopDebugLog.warn("SI", "Continuous SI readout requested with no Race File open")
                return
            }
            val preflightWarning = raceOpsPreflightWarning(
                currentProject,
                protectedCourseInfoByCategoryId.takeIf { isProtectedCourseStateAvailable(currentProject) } ?: emptyMap(),
                isProtectedCourseStateAvailable(currentProject)
            )
            val stopRequested = AtomicBoolean(false)
            val timeoutNoticeLogged = AtomicBoolean(false)
            continuousSiReadoutStopRequested = stopRequested
            isContinuousSiReadoutActive = true
            siDownloadStatusText = "Continuous SI readout is running; insert SI cards and keep each seated until it reads."
            projectStatusText = preflightWarning ?: "Continuous SI readout running..."
            preflightWarning?.let { DesktopDebugLog.warn("Readiness", it) }
            DesktopDebugLog.info("SI", "Continuous SI readout started")
            appCoroutineScope.launch {
                val result = runCatching {
                    withContext(Dispatchers.IO) {
                        siPortMutex.withLock {
                            desktopSportIdentReadoutService().downloadUntilTimeout(
                                maxCards = Int.MAX_VALUE,
                                onDownload = { download ->
                                    appCoroutineScope.launch {
                                        runCatching {
                                            when (appendSportIdentDownload(download)) {
                                                DesktopSportIdentAppendOutcome.Added -> {
                                                    projectStatusText = "Downloaded SI card ${download.readout.siNumber}."
                                                    recordActivity("Downloaded SI card ${download.readout.siNumber}.")
                                                    DesktopDebugLog.info("SI", "Downloaded SI card ${download.readout.siNumber}")
                                                    siDownloadStatusText =
                                                        "Continuous SI readout running; waiting for the next card."
                                                }
                                                DesktopSportIdentAppendOutcome.PracticeInForestStarted -> {
                                                    projectStatusText =
                                                        "Started SI card ${download.readout.siNumber}; waiting for finish readout."
                                                    recordActivity("Started SI card ${download.readout.siNumber}.")
                                                    DesktopDebugLog.info(
                                                        "SI",
                                                        "Started SI card ${download.readout.siNumber} in forest"
                                                    )
                                                    siDownloadStatusText =
                                                        "Practice start recorded; waiting for the next card."
                                                }
                                                DesktopSportIdentAppendOutcome.PracticeInForestAlreadyStarted -> {
                                                    projectStatusText =
                                                        "SI card ${download.readout.siNumber} is already in forest."
                                                    DesktopDebugLog.info(
                                                        "SI",
                                                        "SI card ${download.readout.siNumber} already in forest"
                                                    )
                                                    siDownloadStatusText =
                                                        "Practice card already in forest; waiting for the next card."
                                                }
                                                DesktopSportIdentAppendOutcome.DuplicateIgnored -> {
                                                    projectStatusText =
                                                        "SI card ${download.readout.siNumber} was already downloaded."
                                                    DesktopDebugLog.warn(
                                                        "SI",
                                                        "Duplicate SI card ${download.readout.siNumber} ignored"
                                                    )
                                                    if (isReadoutAlertSoundEnabled) {
                                                        beepDesktopReadoutAlert()
                                                    }
                                                    siDownloadStatusText =
                                                        "Duplicate SI card ignored; continuous SI readout is still running."
                                                }
                                                DesktopSportIdentAppendOutcome.DuplicateReplaced -> {
                                                    projectStatusText =
                                                        "Replaced existing readout for SI card ${download.readout.siNumber}."
                                                    recordActivity("Replaced SI readout ${download.readout.siNumber}.")
                                                    DesktopDebugLog.info(
                                                        "SI",
                                                        "Duplicate SI card ${download.readout.siNumber} replaced"
                                                    )
                                                    siDownloadStatusText =
                                                        "Duplicate SI card replaced; waiting for the next card."
                                                }
                                                DesktopSportIdentAppendOutcome.DuplicateCreatedNew -> {
                                                    projectStatusText =
                                                        "Created new duplicate readout for SI card ${download.readout.siNumber}."
                                                    recordActivity("Stored duplicate SI readout ${download.readout.siNumber}.")
                                                    DesktopDebugLog.info(
                                                        "SI",
                                                        "Duplicate SI card ${download.readout.siNumber} stored as new readout"
                                                    )
                                                    siDownloadStatusText =
                                                        "Duplicate SI card stored as a new readout; waiting for the next card."
                                                }
                                            }
                                        }.onFailure { error ->
                                            projectStatusText = "SI download failed: ${error.message ?: error::class.simpleName}"
                                            siDownloadStatusText = projectStatusText
                                            DesktopDebugLog.error("SI", projectStatusText)
                                            stopRequested.set(true)
                                        }
                                    }
                                },
                                onTimeout = {
                                    appCoroutineScope.launch {
                                        if (!stopRequested.get()) {
                                            siDownloadStatusText = "Continuous SI readout is running; waiting for an SI card."
                                            projectStatusText = siDownloadStatusText ?: projectStatusText
                                            if (timeoutNoticeLogged.compareAndSet(false, true)) {
                                                DesktopDebugLog.warn(
                                                    "SI",
                                                    "Continuous SI readout timed out waiting for a card; continuing"
                                                )
                                            }
                                        }
                                    }
                                },
                                shouldContinue = { !stopRequested.get() },
                                continueAfterTimeout = true
                            )
                        }
                    }
                }
                result.onFailure { error ->
                    projectStatusText = "SI continuous download failed: ${error.message ?: error::class.simpleName}"
                    siDownloadStatusText = projectStatusText
                    DesktopDebugLog.error("SI", projectStatusText)
                }
                if (stopRequested.get() && result.isSuccess) {
                    projectStatusText = "Continuous SI readout stopped."
                    siDownloadStatusText = null
                    DesktopDebugLog.info("SI", "Continuous SI readout stopped")
                }
                isContinuousSiReadoutActive = false
                continuousSiReadoutStopRequested = null
            }
        }

        suspend fun readCompetitorSiCardForAddRow(): DesktopCompetitorSiCardDraft {
            check(!isDownloadingSiReadout && !isContinuousSiReadoutActive && !isReadingCompetitorSiCard) {
                "Another SI card read is already active."
            }
            isReadingCompetitorSiCard = true
            siDownloadStatusText = "Waiting for SI card for competitor entry. Keep the card seated until the read finishes."
            projectStatusText = "Waiting for SI card..."
            DesktopDebugLog.info("SI", "Competitor SI-card read started")
            return try {
                val download = withContext(Dispatchers.IO) {
                    siPortMutex.withLock {
                        downloadDesktopSportIdentCardReadout()
                    }
                }
                val cardHolder = download.readout.cardHolder
                val draft = DesktopCompetitorSiCardDraft(
                    siNumber = download.readout.siNumber,
                    firstName = cardHolder?.firstName,
                    lastName = cardHolder?.lastName,
                    club = cardHolder?.club
                )
                projectStatusText = "Read SI card ${download.readout.siNumber} for competitor entry."
                siDownloadStatusText = null
                DesktopDebugLog.info("SI", "Read SI card ${download.readout.siNumber} for competitor entry")
                draft
            } catch (error: Throwable) {
                projectStatusText = "SI card read failed: ${error.message ?: error::class.simpleName}"
                siDownloadStatusText = projectStatusText
                DesktopDebugLog.error("SI", projectStatusText)
                throw error
            } finally {
                isReadingCompetitorSiCard = false
            }
        }

        fun sendRobisLiveResults(automatic: Boolean = false) {
            if (isSendingLiveResults) {
                return
            }
            val currentProjectForPlan = projectSession.currentProject
            if (currentProjectForPlan == null) {
                if (!automatic) {
                    projectStatusText = "Open or create a Race File before sending live results."
                }
                return
            }
            if (currentProjectForPlan.raceData.race.apiKey.isBlank()) {
                if (!automatic) {
                    projectStatusText = "Set the race API key before sending ROBIS live results."
                }
                return
            }
            if (!EventResultSending.plan(currentProjectForPlan.raceData).hasCandidates) {
                if (!automatic) {
                    projectStatusText = "There are no unsent matched results to send."
                }
                return
            }
            val preflightWarning = raceOpsPreflightWarning(
                currentProjectForPlan,
                protectedCourseInfoByCategoryId.takeIf { isProtectedCourseStateAvailable(currentProjectForPlan) } ?: emptyMap(),
                isProtectedCourseStateAvailable(currentProjectForPlan)
            )
            isSendingLiveResults = true
            if (!automatic) {
                projectStatusText = preflightWarning?.let { "$it Sending live results to ROBIS..." }
                    ?: "Sending live results to ROBIS..."
                preflightWarning?.let { DesktopDebugLog.warn("Readiness", it) }
            }
            appCoroutineScope.launch {
                val sendResult = runCatching {
                    withContext(Dispatchers.IO) {
                        val currentProject = requireNotNull(projectSession.currentProject)
                        DesktopRobisLiveResultSender().sendUnsent(
                            projectFile = currentProject,
                            apiKey = currentProject.raceData.race.apiKey
                        )
                    }
                }
                sendResult.onSuccess { result ->
                    projectFile = projectSession.updateCurrentProject { result.projectFile }
                    syncProjectState()
                    recordActivity("Sent ${result.sentCount} live results to ROBIS.")
                    projectStatusText = "Sent ${result.sentCount} live result${if (result.sentCount == 1) "" else "s"} to ROBIS."
                }.onFailure { error ->
                    projectStatusText = "ROBIS send failed: ${error.message ?: error::class.simpleName}"
                }
                isSendingLiveResults = false
            }
        }

        LaunchedEffect(Unit) {
            while (true) {
                delay(DesktopLiveResultSendIntervalMs)
                if (isBackgroundLiveResultSendingEnabled) {
                    sendRobisLiveResults(automatic = true)
                }
            }
        }

        LaunchedEffect(Unit) {
            while (true) {
                delay(30_000L)
                raceClockTick += 1
            }
        }

        fun saveCurrentProject(overwriteEventDefinitionChanges: Boolean = false): Boolean {
            if (projectSession.currentPath == null) {
                val path = DesktopFileDialogs.chooseSaveProject(
                    projectSession.currentProject?.raceData?.race?.name
                ) ?: return false
                return runCatching {
                    projectSession.saveAs(path)
                    val seriesRefreshWarning = projectSession.currentProject?.let { savedProject ->
                        refreshSavedEventSeriesMetadata(savedProject, path)
                    }
                    newEventDraftProject = null
                    hasUnsavedEventDefinitionChanges = false
                    isEventDefinitionSaveDialogVisible = false
                    syncProjectState()
                    DesktopLastEventFilePreferences.rememberEventFile(path)
                    projectStatusText = buildString {
                        append("Saved ${path.fileName}")
                        if (seriesRefreshWarning != null) {
                            append(". ")
                            append(seriesRefreshWarning)
                        }
                    }
                    val settingsLog = projectSession.currentProject?.startDrawSettingsLogText().orEmpty()
                    DesktopDebugLog.info("EventFile", "Saved ${path.fileName} $settingsLog")
                }.onFailure { error ->
                    projectStatusText = "Save failed: ${error.message ?: error::class.simpleName}"
                    DesktopDebugLog.error("EventFile", "Save failed: ${error.message ?: error::class.simpleName}")
                }.isSuccess
            }
            if (
                DesktopEventDefinitionSaveProtection.shouldPromptBeforeSave(
                    currentPath = projectSession.currentPath,
                    hasUnsavedEventDefinitionChanges = hasUnsavedEventDefinitionChanges,
                    overwriteEventDefinitionChanges = overwriteEventDefinitionChanges
                )
            ) {
                isEventDefinitionSaveDialogVisible = true
                projectStatusText = DesktopEventDefinitionSaveProtection.statusText
                return false
            }
            return runCatching {
                projectSession.save()
                val savedPath = projectSession.currentPath
                val seriesRefreshWarning = if (savedPath != null) {
                    projectSession.currentProject?.let { savedProject ->
                        refreshSavedEventSeriesMetadata(savedProject, savedPath)
                    }
                } else {
                    null
                }
                newEventDraftProject = null
                hasUnsavedEventDefinitionChanges = false
                isEventDefinitionSaveDialogVisible = false
                syncProjectState()
                projectSession.currentPath?.let { savedPath ->
                    DesktopLastEventFilePreferences.rememberEventFile(
                        DesktopEventSeriesArchiveWorkspaces.containerPathFor(savedPath) ?: savedPath
                    )
                }
                val savedDisplayPath = projectSession.currentPath?.let { savedPath ->
                    DesktopEventSeriesArchiveWorkspaces.containerPathFor(savedPath) ?: savedPath
                }
                projectStatusText = buildString {
                    append("Saved ${savedDisplayPath?.fileName ?: "Race File"}")
                    if (seriesRefreshWarning != null) {
                        append(". ")
                        append(seriesRefreshWarning)
                    }
                }
                val settingsLog = projectSession.currentProject?.startDrawSettingsLogText().orEmpty()
                DesktopDebugLog.info(
                    "EventFile",
                    "Saved ${projectSession.currentPath?.fileName ?: "Race File"} $settingsLog"
                )
            }.onFailure { error ->
                projectStatusText = "Save failed: ${error.message ?: error::class.simpleName}"
                DesktopDebugLog.error("EventFile", "Save failed: ${error.message ?: error::class.simpleName}")
            }.isSuccess
        }

        fun createEventSeriesWithCurrentEvent() {
            val currentProject = projectSession.currentProject ?: run {
                projectStatusText = "Open or create a Race File before creating a Race Series."
                return
            }
            val currentPath = projectSession.currentPath ?: run {
                projectStatusText = "Save this Race File before creating a Race Series."
                return
            }
            val seriesFolder = currentPath.parent ?: run {
                projectStatusText = "Race Series creation failed: Race File has no parent folder."
                return
            }
            val defaultContainerName =
                "${org.openardf.radiooracle.shared.event.EventSeriesPackageContents.safePackageFileStem(currentProject.raceData.race.name)}" +
                    org.openardf.radiooracle.shared.event.EVENT_SERIES_ARCHIVE_FILE_SUFFIX
            val containerPath = DesktopFileDialogs.chooseSaveEventSeries(defaultContainerName) ?: return
            runCatching {
                val result = DesktopEventSeriesActions.createSeriesWithEvent(
                    seriesFolder = seriesFolder,
                    seriesId = "${UUID.randomUUID()}-series",
                    seriesName = DesktopEventSeriesActions.DEFAULT_SERIES_NAME,
                    eventPath = currentPath,
                    eventProjectFile = currentProject
                )
                val archiveEvent = result.seriesFile.events.single().copy(
                    eventFilePath = DesktopProjectFilePaths.defaultProjectFileName(
                        result.eventProjectFile.raceData.race.name
                    )
                )
                val archive = EventSeriesArchive(
                    seriesFile = result.seriesFile.copy(events = listOf(archiveEvent)),
                    membersBySeriesEventId = mapOf(
                        archiveEvent.seriesEventId to result.eventProjectFile
                    )
                )
                val workspace = DesktopEventSeriesArchiveWorkspaces.create(
                    containerPath,
                    archive,
                    replaceExisting = true
                )
                val memberPath = workspace.memberPath(archiveEvent)
                projectFile = projectSession.open(memberPath)
                syncProjectState()
                DesktopLastEventFilePreferences.rememberEventFile(containerPath)
                projectStatusText =
                    "Created ${containerPath.fileName} and copied the active Race File into the new series. " +
                        "The original standalone Race File remains as a safety copy."
                DesktopDebugLog.info(
                    "EventSeries",
                    "Created ${containerPath.fileName} for ${currentPath.fileName} " +
                        "seriesId=${result.seriesFile.seriesId} " +
                        "seriesEventId=${result.eventProjectFile.seriesLink?.seriesEventId.orEmpty()}"
                )
                recordActivity(projectStatusText)
            }.onFailure { error ->
                projectStatusText = "Create Race Series failed: ${error.message ?: error::class.simpleName}"
                DesktopDebugLog.error("EventSeries", projectStatusText)
            }
        }

        fun linkCurrentEventToSeries() {
            val currentProject = projectSession.currentProject ?: run {
                projectStatusText = "Open or create a Race File before linking to a Race Series."
                return
            }
            val currentPath = projectSession.currentPath ?: run {
                projectStatusText = "Save this Race File before linking to a Race Series."
                return
            }
            val manifestPath = DesktopFileDialogs.chooseOpenEventSeries() ?: return
            runCatching {
                if (DesktopProjectFilePaths.isEventSeriesArchiveName(manifestPath.fileName.toString())) {
                    val existingWorkspace = DesktopEventSeriesArchiveWorkspaces.workspaceFor(currentPath)
                    require(existingWorkspace == null || existingWorkspace.containerPath == manifestPath.toAbsolutePath().normalize()) {
                        "Move a Race File out of its current series before adding it to another series."
                    }
                    if (existingWorkspace != null) {
                        projectStatusText = "This Race File already belongs to ${existingWorkspace.containerPath.fileName}."
                        return@runCatching
                    }
                    val workspace = DesktopEventSeriesArchiveWorkspaces.open(manifestPath)
                    val existingIds = workspace.archive.seriesFile.events.mapTo(hashSetOf()) { it.seriesEventId }
                    val baseSeriesEventId = currentProject.raceData.race.id
                    var seriesEventId = baseSeriesEventId
                    var idIndex = 2
                    while (seriesEventId in existingIds) {
                        seriesEventId = "$baseSeriesEventId-$idIndex"
                        idIndex += 1
                    }
                    val eventFilePath = uniqueArchiveEventFilePath(
                        workspace.archive,
                        DesktopProjectFilePaths.defaultProjectFileName(currentProject.raceData.race.name)
                    )
                    val nextOrder = (workspace.archive.seriesFile.events.maxOfOrNull { it.order } ?: -1) + 1
                    val race = currentProject.raceData.race
                    val event = EventSeriesEvent(
                        seriesEventId = seriesEventId,
                        eventFilePath = eventFilePath,
                        order = nextOrder,
                        displayName = race.name,
                        startDateTimeIso = race.startDateTimeIso,
                        formatLabel = race.raceType.name
                    )
                    workspace.addMember(event, currentProject)
                    projectFile = projectSession.open(workspace.memberPath(event))
                    syncProjectState()
                    DesktopLastEventFilePreferences.rememberEventFile(workspace.containerPath)
                    projectStatusText =
                        "Added this Race File to ${workspace.containerPath.fileName}. The original standalone file remains unchanged."
                    recordActivity(projectStatusText)
                    return@runCatching
                }
                val seriesFile = DesktopEventSeriesFiles.read(manifestPath)
                val seriesFolder = requireNotNull(manifestPath.parent) {
                    "Race Series manifest has no parent folder."
                }
                val result = DesktopEventSeriesActions.linkCurrentEvent(
                    seriesFile = seriesFile,
                    eventPath = currentPath,
                    seriesFolder = seriesFolder,
                    eventProjectFile = currentProject
                )
                DesktopEventSeriesFiles.write(manifestPath, result.seriesFile)
                projectFile = projectSession.updateCurrentProject { result.eventProjectFile }
                projectSession.save()
                syncProjectState()
                projectStatusText = "Linked this Race File to ${manifestPath.fileName}."
                DesktopDebugLog.info(
                    "EventSeries",
                    "Linked ${currentPath.fileName} to ${manifestPath.fileName} " +
                        "seriesId=${result.seriesFile.seriesId} " +
                        "seriesEventId=${result.eventProjectFile.seriesLink?.seriesEventId.orEmpty()}"
                )
                recordActivity(projectStatusText)
            }.onFailure { error ->
                projectStatusText = "Link Race Series failed: ${error.message ?: error::class.simpleName}"
                DesktopDebugLog.error("EventSeries", projectStatusText)
            }
        }

        fun removeCurrentEventFromSeries() {
            if (
                (projectSession.hasUnsavedChanges || hasUnsavedEventDefinitionChanges) &&
                !saveCurrentProject()
            ) {
                return
            }
            val currentProject = projectSession.currentProject ?: run {
                projectStatusText = "Open or create a Race File before removing a series link."
                return
            }
            val manifestPath = currentSeriesManifestPath() ?: run {
                projectStatusText = "Series manifest not found near this Race File; no link was removed."
                return
            }
            val workspace = DesktopEventSeriesArchiveWorkspaces.workspaceFor(manifestPath)
            if (workspace != null) {
                val link = currentProject.seriesLink ?: run {
                    projectStatusText = "This Race File is not linked to the open series."
                    return
                }
                val standalonePath = DesktopFileDialogs.chooseSaveProject(
                    raceName = currentProject.raceData.race.name
                ) ?: return
                runCatching {
                    val removal = workspace.removeMember(link.seriesEventId, standalonePath)
                    projectFile = projectSession.open(standalonePath)
                    if (removal.remainingArchive == null) {
                        DesktopEventSeriesArchiveWorkspaces.close(workspace)
                    }
                    syncProjectState()
                    DesktopLastEventFilePreferences.rememberEventFile(standalonePath)
                    projectStatusText = if (removal.remainingArchive == null) {
                        "Saved ${standalonePath.fileName} and removed the now-empty ${workspace.containerPath.fileName}."
                    } else {
                        "Removed this race from ${workspace.containerPath.fileName} and saved it as ${standalonePath.fileName}."
                    }
                    recordActivity(projectStatusText)
                }.onFailure { error ->
                    projectStatusText = "Remove Race from Series failed: ${error.message ?: error::class.simpleName}"
                    DesktopDebugLog.error("EventSeries", projectStatusText)
                }
                return
            }
            runCatching {
                val seriesFile = DesktopEventSeriesFiles.read(manifestPath)
                val result = DesktopEventSeriesActions.removeCurrentEvent(seriesFile, currentProject)
                DesktopEventSeriesFiles.write(manifestPath, result.seriesFile)
                projectFile = projectSession.updateCurrentProject { result.eventProjectFile }
                projectSession.save()
                syncProjectState()
                projectStatusText = "Removed this Race File from ${manifestPath.fileName}."
                recordActivity(projectStatusText)
            }.onFailure { error ->
                projectStatusText = "Remove Race Series link failed: ${error.message ?: error::class.simpleName}"
            }
        }

        fun validateCurrentEventSeries() {
            val manifestPath = currentSeriesManifestPath() ?: run {
                eventSeriesValidationState = null
                eventSeriesValidationEventPath = projectSession.currentPath?.toAbsolutePath()?.normalize()
                projectStatusText = "Series manifest not found near this Race File."
                return
            }
            runCatching {
                val session = DesktopEventSeriesSession(DesktopEventSeriesFiles)
                session.open(manifestPath)
                val issues = session.validateLinkedEvents()
                eventSeriesValidationState = EventSeriesValidationUiState(
                    manifestPath = manifestPath,
                    issues = issues
                )
                eventSeriesValidationEventPath = projectSession.currentPath?.toAbsolutePath()?.normalize()
                projectStatusText = if (issues.isEmpty()) {
                    "Race Series validation passed."
                } else {
                    "Race Series validation found ${issues.size} issue${if (issues.size == 1) "" else "s"}: ${issues.first().message}"
                }
            }.onFailure { error ->
                val message = error.message ?: error::class.simpleName ?: "Unknown error"
                eventSeriesValidationState = EventSeriesValidationUiState(
                    manifestPath = manifestPath,
                    issues = emptyList(),
                    errorMessage = message
                )
                eventSeriesValidationEventPath = projectSession.currentPath?.toAbsolutePath()?.normalize()
                projectStatusText = "Race Series validation failed: $message"
            }
        }

        fun addEventToCurrentSeries() {
            val currentProject = projectSession.currentProject ?: run {
                projectStatusText = "Open or create a Race File before adding another race to a series."
                return
            }
            if (currentProject.seriesLink == null) {
                projectStatusText = "Link this Race File to a Race Series before adding another series race."
                return
            }
            val manifestPath = currentSeriesManifestPath() ?: run {
                projectStatusText = "Series manifest not found near this Race File."
                return
            }
            val eventPath = DesktopFileDialogs.chooseEventSeriesMemberEventFile() ?: return
            runCatching {
                val workspace = DesktopEventSeriesArchiveWorkspaces.workspaceFor(manifestPath)
                if (workspace != null) {
                    val eventProjectFile = DesktopProjectFiles.read(eventPath)
                    val existingIds = workspace.archive.seriesFile.events.mapTo(hashSetOf()) { it.seriesEventId }
                    val baseSeriesEventId = eventProjectFile.raceData.race.id
                    var seriesEventId = baseSeriesEventId
                    var idIndex = 2
                    while (seriesEventId in existingIds) {
                        seriesEventId = "$baseSeriesEventId-$idIndex"
                        idIndex += 1
                    }
                    val eventFilePath = uniqueArchiveEventFilePath(
                        workspace.archive,
                        eventPath.fileName.toString()
                    )
                    val race = eventProjectFile.raceData.race
                    val event = EventSeriesEvent(
                        seriesEventId = seriesEventId,
                        eventFilePath = eventFilePath,
                        order = (workspace.archive.seriesFile.events.maxOfOrNull { it.order } ?: -1) + 1,
                        displayName = race.name,
                        startDateTimeIso = race.startDateTimeIso,
                        formatLabel = race.raceType.name
                    )
                    workspace.addMember(event, eventProjectFile)
                    refreshSeriesEventSummaries()
                    projectStatusText =
                        "Added ${eventPath.fileName} to ${workspace.containerPath.fileName}; series now has ${workspace.archive.memberCount} races."
                    recordActivity(projectStatusText)
                    return@runCatching
                }
                val seriesFile = DesktopEventSeriesFiles.read(manifestPath)
                val seriesFolder = requireNotNull(manifestPath.parent) {
                    "Race Series manifest has no parent folder."
                }
                val eventProjectFile = DesktopEventSeriesFiles.readEvent(eventPath)
                val result = DesktopEventSeriesActions.addEventToSeries(
                    seriesFile = seriesFile,
                    eventPath = eventPath,
                    seriesFolder = seriesFolder,
                    eventProjectFile = eventProjectFile
                )
                val addedLink = requireNotNull(result.eventProjectFile.seriesLink) {
                    "Added Race File did not receive a Race Series backlink."
                }
                // The added Race File is not the currently open document, so write it through the series store.
                DesktopEventSeriesFiles.write(manifestPath, result.seriesFile)
                DesktopEventSeriesFiles.writeEvent(eventPath, result.eventProjectFile)
                val verifiedSeriesFile = DesktopEventSeriesFiles.read(manifestPath)
                val verifiedEvent = requireNotNull(
                    verifiedSeriesFile.events.firstOrNull { it.seriesEventId == addedLink.seriesEventId }
                ) {
                    "Race Series manifest write did not include ${eventPath.fileName}."
                }
                refreshSeriesEventSummaries()
                DesktopDebugLog.info(
                    "EventSeries",
                    "Added event manifest=$manifestPath eventFile=$eventPath beforeCount=${seriesFile.events.size} " +
                        "afterCount=${verifiedSeriesFile.events.size} seriesEventId=${addedLink.seriesEventId} " +
                        "eventFilePath=${verifiedEvent.eventFilePath}"
                )
                val actionVerb = if (verifiedSeriesFile.events.size > seriesFile.events.size) "Added" else "Updated"
                projectStatusText = "$actionVerb ${eventPath.fileName} in ${manifestPath.fileName}; series now has ${verifiedSeriesFile.events.size} races."
                recordActivity(projectStatusText)
            }.onFailure { error ->
                projectStatusText = "Add Race to Series failed: ${error.message ?: error::class.simpleName}"
                DesktopDebugLog.error("EventSeries", projectStatusText)
            }
        }

