        fun applyCategoryListEdit(edit: DesktopCategoryListEdit): Boolean {
            return when (
                val attempt = DesktopCategoryActions.attemptListEdit(
                    projectFile = projectSession.currentProject,
                    edit = edit,
                    protectedCourseInfoByCategoryId = protectedCourseInfoByCategoryId,
                    protectedIdealOrderByCategoryId = protectedIdealOrderByCategoryId
                )
            ) {
                is DesktopCategoryListEditAttempt.RequiresCourseUnlock -> {
                    pendingProtectedCourseActionRequest =
                        PendingProtectedCourseActionRequest.ActivateCategory(attempt.requestedName)
                    pendingCourseKmlKmzUnlockAction = CourseKmlKmzUnlockAction.ActivateCategory
                    projectStatusText =
                        "Unlock course data to activate ${attempt.mappingName} with its stored route, metrics, and assigned controls."
                    true
                }
                is DesktopCategoryListEditAttempt.Applied -> {
                    val outcome = attempt.result
                    projectFile = projectSession.updateCurrentProject { outcome.projectFile }
                    protectedCourseInfoByCategoryId = outcome.protectedCourseInfoByCategoryId
                    protectedIdealOrderByCategoryId = outcome.protectedIdealOrderByCategoryId
                    hasUnsavedChanges = projectSession.hasUnsavedChanges
                    projectStatusText = outcome.statusText
                    true
                }
                is DesktopCategoryListEditAttempt.Failed -> {
                    projectStatusText = attempt.message
                    false
                }
            }
        }

        fun saveAsCurrentProject(suggestedFileName: String? = null): Boolean {
            val path = DesktopFileDialogs.chooseSaveProject(
                raceName = projectSession.currentProject?.raceData?.race?.name,
                suggestedFileName = suggestedFileName
            )
                ?: return false
            return runCatching {
                val currentPath = projectSession.currentPath
                val currentWorkspace = currentPath?.let(DesktopEventSeriesArchiveWorkspaces::workspaceFor)
                val seriesRefreshWarning = if (currentWorkspace == null) {
                    projectSession.saveAs(path)
                    projectSession.currentProject?.let { savedProject ->
                        refreshSavedEventSeriesMetadata(savedProject, path)
                    }
                } else {
                    val standaloneProject = EventProjectEditor.removeSeriesLink(
                        requireNotNull(projectSession.currentProject)
                    )
                    DesktopProjectFiles.write(path, standaloneProject)
                    projectSession.open(path)
                    null
                }
                hasUnsavedEventDefinitionChanges = false
                isEventDefinitionSaveDialogVisible = false
                syncProjectState()
                DesktopLastEventFilePreferences.rememberEventFile(path)
                projectStatusText = buildString {
                    append("Saved ${path.fileName}")
                    if (currentWorkspace != null) {
                        append(" as a standalone copy; the original race remains in ")
                        append(currentWorkspace.containerPath.fileName)
                    }
                    if (seriesRefreshWarning != null) {
                        append(". ")
                        append(seriesRefreshWarning)
                    }
                }
                val settingsLog = projectSession.currentProject?.startDrawSettingsLogText().orEmpty()
                DesktopDebugLog.info("EventFile", "Saved As ${path.fileName} $settingsLog")
            }.onFailure { error ->
                projectStatusText = "Save failed: ${error.message ?: error::class.simpleName}"
                DesktopDebugLog.error("EventFile", "Save As failed: ${error.message ?: error::class.simpleName}")
            }.isSuccess
        }

