internal fun desktopTopBarEventText(projectFile: EventProjectFile?): String =
    projectFile?.raceData?.race?.name
        ?.takeIf { it.isNotBlank() }
        ?.let { "Race: $it" }
        ?: "No race file loaded"

internal fun desktopTopBarSeriesText(seriesContext: EventSeriesUiContext): String =
    "Series: ${seriesContext.seriesName.ifBlank { "Untitled Series" }}"

internal fun desktopParentSeriesText(seriesContext: EventSeriesUiContext?): String? =
    seriesContext?.seriesName
        ?.ifBlank { "Untitled Series" }
        ?.let { "Parent Series: $it" }

internal fun desktopEventFileFolderText(eventFilePath: Path?, workingFolder: Path): String {
    val persistedEventPath = eventFilePath?.let { path ->
        DesktopEventSeriesArchiveWorkspaces.containerPathFor(path) ?: path
    }
    val directory = persistedEventPath?.parent ?: workingFolder
    val directoryText = directory.toAbsolutePath().normalize().toString()
    return if (persistedEventPath == null) {
        "Race File Folder: $directoryText (first save default)"
    } else {
        "Race File Folder: $directoryText"
    }
}

private fun EventRaceData.readoutEditDraft(resultId: String): DesktopReadoutEditDraft? {
    competitorData.forEach { data ->
        val readoutData = data.readoutData ?: return@forEach
        if (readoutData.result.id == resultId) {
            val competitor = data.competitorCategory.competitor
            val isPractice = race.raceLevel == RaceLevel.PRACTICE
            val elapsedBaseSeconds = if (isPractice) readoutData.result.startTimeSeconds else raceStartSecondsOfDay(race.startDateTimeIso)
            return DesktopReadoutEditDraft(
                resultId = resultId,
                competitorName = competitor.fullName(),
                matched = true,
                startSeconds = if (isPractice && readoutData.result.startTimeSeconds != null) {
                    0L.toReadoutElapsedText()
                } else {
                    elapsedRaceTimeText(readoutData.result.startTimeSeconds)
                },
                finishSeconds = elapsedRaceTimeText(readoutData.result.finishTimeSeconds, elapsedBaseSeconds),
                startSiTime = readoutData.result.startTimeSeconds.toReadoutSiTimeText(),
                finishSiTime = readoutData.result.finishTimeSeconds.toReadoutSiTimeText(),
                elapsedBaseSeconds = elapsedBaseSeconds,
                controlPunches = readoutData.controlPunchRows(this, elapsedBaseSeconds),
                resultStatus = readoutData.result.resultStatus,
                categoryId = readoutData.result.categoryId ?: competitor.categoryId,
                originalCategoryId = competitor.categoryId,
                isPractice = isPractice,
                issueExplanation = readoutData.readoutIssueExplanation()
            )
        }
    }
    unmatchedReadoutData.forEach { readoutData ->
        if (readoutData.result.id == resultId) {
            val isPractice = race.raceLevel == RaceLevel.PRACTICE
            val elapsedBaseSeconds = if (isPractice) readoutData.result.startTimeSeconds else raceStartSecondsOfDay(race.startDateTimeIso)
            return DesktopReadoutEditDraft(
                resultId = resultId,
                competitorName = readoutData.result.cardName ?: "",
                matched = false,
                startSeconds = if (isPractice && readoutData.result.startTimeSeconds != null) {
                    0L.toReadoutElapsedText()
                } else {
                    elapsedRaceTimeText(readoutData.result.startTimeSeconds)
                },
                finishSeconds = elapsedRaceTimeText(readoutData.result.finishTimeSeconds, elapsedBaseSeconds),
                startSiTime = readoutData.result.startTimeSeconds.toReadoutSiTimeText(),
                finishSiTime = readoutData.result.finishTimeSeconds.toReadoutSiTimeText(),
                elapsedBaseSeconds = elapsedBaseSeconds,
                controlPunches = readoutData.controlPunchRows(this, elapsedBaseSeconds),
                resultStatus = readoutData.result.resultStatus,
                categoryId = readoutData.result.categoryId,
                originalCategoryId = null,
                isPractice = isPractice,
                issueExplanation = readoutData.readoutIssueExplanation()
            )
        }
    }
    return null
}

private fun EventRaceData.readoutByResultId(resultId: String): EventReadoutData? =
    competitorData
        .mapNotNull { it.readoutData }
        .plus(unmatchedReadoutData)
        .firstOrNull { it.result.id == resultId }

private fun saveDesktopReadoutEdit(
    currentProject: EventProjectFile,
    updatedDraft: DesktopReadoutEditDraft
): DesktopReadoutEditSaveResult {
    val controlPunchesText = updatedDraft.controlPunches.toControlPunchesText(currentProject.raceData.controls)
    val recalculatedProject = EventProjectEditor.updateReadoutEdit(
        projectFile = currentProject,
        resultId = updatedDraft.resultId,
        startSeconds = updatedDraft.startSeconds,
        finishSeconds = updatedDraft.finishSeconds,
        controlPunchesText = controlPunchesText,
        resultStatus = updatedDraft.resultStatus,
        categoryId = updatedDraft.categoryId,
        updateCompetitorCategory = updatedDraft.updateCompetitorCategory,
        punchIdFactory = { index, type -> "edited-punch-check-${UUID.randomUUID()}-$index-${type.name}" },
        startSiTime = updatedDraft.startSiTime,
        finishSiTime = updatedDraft.finishSiTime,
        recalculateStatus = true
    )
    val issueNotice = recalculatedProject.raceData.readoutSaveIssueNotice(
        resultId = updatedDraft.resultId,
        selectedStatus = updatedDraft.resultStatus,
        statusWasEdited = updatedDraft.resultStatusEdited
    )
    val updatedProject = EventProjectEditor.updateReadoutEdit(
        projectFile = currentProject,
        resultId = updatedDraft.resultId,
        startSeconds = updatedDraft.startSeconds,
        finishSeconds = updatedDraft.finishSeconds,
        controlPunchesText = controlPunchesText,
        resultStatus = updatedDraft.resultStatus,
        categoryId = updatedDraft.categoryId,
        updateCompetitorCategory = updatedDraft.updateCompetitorCategory,
        punchIdFactory = { index, type -> "edited-punch-${UUID.randomUUID()}-$index-${type.name}" },
        startSiTime = updatedDraft.startSiTime,
        finishSiTime = updatedDraft.finishSiTime,
        recalculateStatus = !updatedDraft.resultStatusEdited
    )
    return DesktopReadoutEditSaveResult(
        projectFile = updatedProject,
        issueNotice = issueNotice
    )
}

private fun EventRaceData.readoutSaveIssueNotice(
    resultId: String,
    selectedStatus: ResultStatus,
    statusWasEdited: Boolean
): DesktopReadoutSaveIssueNotice? {
    val recalculatedReadout = readoutByResultId(resultId) ?: return null
    val recalculatedStatus = recalculatedReadout.result.resultStatus
    val issueExplanation = recalculatedReadout.readoutIssueExplanation()
    val hasIssue = issueExplanation != null || recalculatedStatus.isCalculatedIssueStatus()
    if (!hasIssue) {
        return null
    }

    val details = buildList {
        issueExplanation?.let(::add)
        if (recalculatedStatus.isCalculatedIssueStatus()) {
            add("Calculated status: ${recalculatedStatus.toDisplayLabel()}.")
        }
    }
    val summary = if (statusWasEdited && selectedStatus != recalculatedStatus) {
        "The result was saved with manual status ${selectedStatus.toDisplayLabel()}, but recalculation still reports ${recalculatedStatus.toDisplayLabel()}."
    } else {
        "The result was saved, but recalculation still reports ${recalculatedStatus.toDisplayLabel()}."
    }
    return DesktopReadoutSaveIssueNotice(
        title = "Result Saved With Remaining Issue",
        summary = summary,
        details = details.distinct()
    )
}

private fun ResultStatus.isCalculatedIssueStatus(): Boolean =
    this != ResultStatus.OK && this != ResultStatus.NO_RANKING

private fun DesktopReadoutSaveIssueNotice.show() {
    val message = buildString {
        append(summary)
        details.forEach { detail ->
            append("\n\n")
            append(detail)
        }
    }
    javax.swing.JOptionPane.showMessageDialog(
        null,
        message,
        title,
        javax.swing.JOptionPane.INFORMATION_MESSAGE
    )
}

private fun EventRaceData.elapsedRaceTimeText(
    daySeconds: Long?,
    elapsedBaseSeconds: Long? = raceStartSecondsOfDay(race.startDateTimeIso)
): String =
    daySeconds?.let { seconds ->
        val elapsedSeconds = if (elapsedBaseSeconds == null) {
            seconds
        } else {
            (seconds - elapsedBaseSeconds).toSportIdentDaySeconds()
        }
        elapsedSeconds.toReadoutElapsedText()
    }.orEmpty()

private fun Long.toReadoutElapsedText(): String =
    DurationFormatter.secondsToFormattedString(this, useMinutes = this < 3_600)

private fun Long?.toReadoutSiTimeText(): String =
    this?.let { seconds ->
        val daySeconds = seconds.toSportIdentDaySeconds()
        DurationFormatter.secondsToFormattedString(daySeconds, useMinutes = false)
    }.orEmpty()

// SPORTident readouts store clock times as seconds within the station day.
private fun Long.toSportIdentDaySeconds(): Long {
    val secondsInDay = SportIdentCodes.SECONDS_DAY
    return ((this % secondsInDay) + secondsInDay) % secondsInDay
}

private fun org.openardf.radiooracle.shared.event.EventReadoutData.controlPunchRows(
    raceData: EventRaceData,
    elapsedBaseSeconds: Long?
): List<DesktopReadoutPunchEditDraft> =
    punches
        .map { aliasPunch -> aliasPunch.punch to aliasPunch.alias?.name }
        .filter { (punch, _) -> punch.punchType == SIRecordType.CONTROL }
        .mapIndexed { index, (punch, aliasName) ->
            val control = raceData.controls.firstOrNull { it.siCode == punch.siCode }
            DesktopReadoutPunchEditDraft(
                rowId = punch.id.ifBlank { "punch-$index-${punch.siCode}" },
                controlId = control?.id,
                siCode = punch.siCode,
                controlText = control?.editPunchToken(raceData.controls)
                    ?: aliasName?.takeIf { it.isNotBlank() }
                    ?: punch.siCode.toString(),
                elapsedTime = raceData.elapsedRaceTimeText(punch.siTimeSeconds, elapsedBaseSeconds),
                siTime = punch.siTimeSeconds.toReadoutSiTimeText(),
                punchStatus = punch.punchStatus
            )
        }

private fun List<DesktopReadoutPunchEditDraft>.toControlPunchesText(controls: List<EventControl>): String {
    val controlsById = controls.associateBy { it.id }
    val sortedControls = controls.sortedWith(compareBy<EventControl> { it.siCode }.thenBy { it.publicDisplayLabel() })
    return joinToString("\n") { punch ->
        val control = punch.controlId?.let(controlsById::get)
        val controlText = control?.editPunchToken(sortedControls) ?: punch.controlText
        "$controlText @ ${punch.elapsedTime.trim()}"
    }
}

private fun raceStartSecondsOfDay(startDateTimeIso: String): Long? {
    val time = startDateTimeIso.substringAfter('T', missingDelimiterValue = "")
        .substringBefore('.')
        .substringBefore('Z')
        .substringBefore('+')
        .substringBefore('-')
    if (time.isBlank()) {
        return null
    }
    val parts = time.split(":")
    if (parts.size < 2) {
        return null
    }
    val hour = parts[0].toLongOrNull() ?: return null
    val minute = parts[1].toLongOrNull() ?: return null
    val second = parts.getOrNull(2)?.toLongOrNull() ?: 0
    return if (hour in 0..23 && minute in 0..59 && second in 0..59) {
        hour * 3_600 + minute * 60 + second
    } else {
        null
    }
}

