internal fun isShareableLocalResultsWebServerUrl(url: String): Boolean =
    runCatching {
        val host = URI(url).host?.lowercase()?.trim('[', ']') ?: return@runCatching false
        host !in setOf("127.0.0.1", "localhost", "::1", "0:0:0:0:0:0:0:1")
    }.getOrDefault(false)

