            EnumPicker(
                selectedValue = awardDisplayMode,
                values = EventAwardDisplayMode.entries,
                label = { it.displayLabel },
                onValueSelected = onSetAwardDisplayMode,
                modifier = Modifier.width(280.dp),
                enabled = awardsEnabled
            )
        }
        Text(
            text = raceAwardSettingsSummary(race),
            color = Color.DarkGray,
            fontSize = 13.sp
        )
    }
}

private fun raceAwardSettingsSummary(race: EventRace?): String =
    when {
        race == null -> "Open or create a Race File before configuring championship award display."
        race.raceLevel == RaceLevel.PRACTICE -> "Practice races do not show championship award eligibility or award positions."
        race.combinedNationalRegionalAwards -> "Competitor setup and awards results show both National and Regional award fields."
        race.raceLevel == RaceLevel.NATIONAL -> "Competitor setup and awards results show National award fields."
        race.raceLevel == RaceLevel.REGIONAL -> "Competitor setup and awards results show Regional award fields."
        else -> "Select National, Regional, or combined National/Regional awards to show championship award fields."
    }

@Composable
private fun CloudflarePagesPublishSettingsPanel(
    settings: DesktopCloudflarePagesPublishSettings,
    settingsRejection: String?,
    projectFile: EventProjectFile?,
    onSave: (DesktopCloudflarePagesPublishSettings) -> Boolean
) {
    var projectNameDraft by remember(settings) { mutableStateOf(settings.projectName) }
    var branchDraft by remember(settings) { mutableStateOf(settings.branch) }
    var accountIdDraft by remember(settings) { mutableStateOf(settings.accountId) }
    var apiTokenDraft by remember(settings) { mutableStateOf(settings.apiToken) }
    var retentionModeDraft by remember(settings) { mutableStateOf(settings.retentionMode) }
    var publicationStatusDraft by remember(settings) { mutableStateOf(settings.publicationStatus) }
    var saveConfirmationText by remember { mutableStateOf<String?>(null) }
    val revealNeedsPassword = cloudflareApiTokenRevealNeedsPassword(projectFile)
    val revealStateKey = projectFile?.raceData?.race?.id to revealNeedsPassword
    var isApiTokenVisible by remember(revealStateKey, settings.apiToken) { mutableStateOf(false) }
    var isTokenRevealDialogVisible by remember(revealStateKey) { mutableStateOf(false) }
    val savedSettings = settings.normalized()
    val rawDraftSettings = DesktopCloudflarePagesPublishSettings(
        projectName = projectNameDraft,
        branch = branchDraft,
        accountId = accountIdDraft,
        apiToken = apiTokenDraft,
        retentionMode = retentionModeDraft,
        publicationStatus = publicationStatusDraft
    )
    val draftSettings = rawDraftSettings.normalized()
    val disabledReason = cloudflarePagesSettingsDisabledReason(
        rawDraftSettings,
        draftSettings,
        savedSettings,
        settingsRejection
    )
    fun submitSettings() {
        if (disabledReason == null && onSave(draftSettings)) {
            saveConfirmationText = "Cloudflare Pages settings saved."
        }
    }
    fun clearSaveConfirmation() {
        saveConfirmationText = null
    }

    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        settingsRejection?.let { rejection ->
            Text(
                text = rejection,
                color = DesktopPalette.Error,
                fontSize = 13.sp,
                fontWeight = FontWeight.Bold
            )
        }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
            TextField(
                value = projectNameDraft,
                onValueChange = {
                    projectNameDraft = it
                    clearSaveConfirmation()
                },
                label = { Text("Pages Project") },
                singleLine = true,
                modifier = Modifier
                    .weight(1f)
                    .commitOnEnter(::submitSettings)
            )
            TextField(
                value = branchDraft,
                onValueChange = {
                    branchDraft = it
                    clearSaveConfirmation()
                },
                label = { Text("Branch") },
                singleLine = true,
                modifier = Modifier
                    .weight(1f)
                    .commitOnEnter(::submitSettings)
            )
        }
        TextField(
            value = accountIdDraft,
            onValueChange = {
                accountIdDraft = it
                clearSaveConfirmation()
            },
            label = { Text("Account ID") },
            singleLine = true,
            modifier = Modifier
                .fillMaxWidth()
                .commitOnEnter(::submitSettings)
        )
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = "Published history",
                color = DesktopPalette.Black,
                fontSize = 13.sp,
                fontWeight = FontWeight.SemiBold
            )
            EnumPicker(
                selectedValue = retentionModeDraft,
                values = DesktopPublicResultsRetentionMode.entries,
                label = DesktopPublicResultsRetentionMode::displayLabel,
                onValueSelected = {
                    retentionModeDraft = it
                    clearSaveConfirmation()
                },
                modifier = Modifier.width(280.dp)
            )
        }
        Text(
            text = retentionModeDraft.description,
            color = Color.DarkGray,
            fontSize = 13.sp
        )
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = "Website result status",
                color = DesktopPalette.Black,
                fontSize = 13.sp,
                fontWeight = FontWeight.SemiBold
            )
            EnumPicker(
                selectedValue = publicationStatusDraft,
                values = PublicResultsPublicationStatus.entries,
                label = PublicResultsPublicationStatus::displayLabel,
                onValueSelected = {
                    publicationStatusDraft = it
                    clearSaveConfirmation()
                },
                modifier = Modifier.width(280.dp)
            )
        }
        Text(
            text = if (publicationStatusDraft == PublicResultsPublicationStatus.OFFICIAL) {
                "Official publishing checks every competitor, bib, result status, and unmatched readout before uploading."
            } else {
                "Preliminary publishing allows updates while results are still being reviewed."
            },
            color = Color.DarkGray,
            fontSize = 13.sp
        )
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.fillMaxWidth()
        ) {
            TextField(
                value = apiTokenDraft,
                onValueChange = {
                    apiTokenDraft = it
                    clearSaveConfirmation()
                },
                label = { Text("API Token") },
                singleLine = true,
                visualTransformation = if (isApiTokenVisible) {
                    VisualTransformation.None
                } else {
                    PasswordVisualTransformation()
                },
                modifier = Modifier
                    .weight(1f)
                    .commitOnEnter(::submitSettings)
            )
            val revealDisabledReason = cloudflareApiTokenRevealDisabledReason(apiTokenDraft)
            DisabledReasonTooltip(
                if (isApiTokenVisible) null else revealDisabledReason
            ) {
                Button(
                    onClick = {
                        if (isApiTokenVisible) {
                            isApiTokenVisible = false
                        } else if (revealNeedsPassword) {
                            isTokenRevealDialogVisible = true
                        } else {
                            isApiTokenVisible = true
                        }
                    },
                    enabled = isApiTokenVisible || revealDisabledReason == null
                ) {
                    ButtonLabel(if (isApiTokenVisible) "Hide API Token" else "Show API Token")
                }
            }
        }
        Text(
            text = if (revealNeedsPassword) {
                "The API token is hidden by default. Showing the stored value requires the current Race Password."
            } else {
                "The API token is hidden by default. Use Show API Token to reveal it; no Race Password is set."
            },
            color = Color.DarkGray,
            fontSize = 13.sp
        )
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            DisabledReasonTooltip(disabledReason) {
                Button(
                    onClick = ::submitSettings,
                    enabled = disabledReason == null
                ) {
                    ButtonLabel("Save Cloudflare Settings")
                }
            }
            saveConfirmationText?.let { confirmation ->
                Text(
                    text = confirmation,
                    color = DesktopPalette.Connected,
                    fontWeight = FontWeight.Bold,
                    fontSize = 13.sp
                )
            }
        }
    }
    if (isTokenRevealDialogVisible && revealNeedsPassword) {
        CloudflareApiTokenRevealDialog(
            onVerify = { password ->
                projectFile?.racePasswordAuthorizesCloudflareTokenReveal(password) == true
            },
            onReveal = {
                isApiTokenVisible = true
                isTokenRevealDialogVisible = false
            },
            onCancel = {
                isTokenRevealDialogVisible = false
            }
        )
    }
}

@Composable
private fun CloudflareApiTokenRevealDialog(
    onVerify: (String) -> Boolean,
    onReveal: () -> Unit,
    onCancel: () -> Unit
) {
    var passwordDraft by remember { mutableStateOf("") }
    var errorText by remember { mutableStateOf<String?>(null) }
    fun submitPassword() {
        if (passwordDraft.isBlank()) {
            return
        }
        if (onVerify(passwordDraft)) {
            passwordDraft = ""
            errorText = null
            onReveal()
        } else {
            errorText = "The Race Password is incorrect."
        }
    }

    AlertDialog(
        onDismissRequest = onCancel,
        title = { Text("Show Cloudflare API Token") },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Text(
                    "This reveals the locally stored Cloudflare API token on screen. Enter the current Race Password to continue."
                )
                TextField(
                    value = passwordDraft,
                    onValueChange = {
                        passwordDraft = it
                        errorText = null
                    },
                    label = { Text("Race Password") },
                    singleLine = true,
                    visualTransformation = PasswordVisualTransformation(),
                    modifier = Modifier
                        .fillMaxWidth()
                        .commitOnEnter(::submitPassword)
                )
                errorText?.let { message ->
                    Text(
                        text = message,
                        color = DesktopPalette.Disconnected,
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        },
        confirmButton = {
            Button(
                onClick = ::submitPassword,
                enabled = passwordDraft.isNotBlank()
            ) {
                Text("Show Token")
            }
        },
        dismissButton = {
            Button(onClick = onCancel) {
                Text("Cancel")
            }
        }
    )
}

internal fun cloudflareApiTokenRevealNeedsPassword(projectFile: EventProjectFile?): Boolean =
    projectFile?.hasEncryptedCategoryData() == true

private fun cloudflareApiTokenRevealDisabledReason(apiToken: String): String? =
    "Save a Cloudflare API token before trying to show it.".takeIf { apiToken.isBlank() }

private fun cloudflarePagesSettingsDisabledReason(
    rawDraftSettings: DesktopCloudflarePagesPublishSettings,
    draftSettings: DesktopCloudflarePagesPublishSettings,
    savedSettings: DesktopCloudflarePagesPublishSettings,
    settingsRejection: String?
): String? =
    when {
        rawDraftSettings.projectName.isBlank() -> "Enter a Cloudflare Pages project name."
        rawDraftSettings.branch.isBlank() -> "Enter a Cloudflare Pages branch."
        rawDraftSettings.accountId.isBlank() -> "Enter the Cloudflare account ID."
        rawDraftSettings.apiToken.isBlank() -> "Enter a Cloudflare Pages API token."
        draftSettings == savedSettings && settingsRejection == null ->
            "Cloudflare Pages publishing settings are already saved."
        else -> null
    }

@Composable
private fun AppSettingsSection(
    title: String,
    content: @Composable ColumnScope.() -> Unit
) {
