/** Shows read-only competitor result rows. */
@Composable
private fun ResultDetailsPanel(
    results: List<EventResultDetails>,
    publicationNotice: String?,
    onUpdateReadoutStatus: (String, ResultStatus) -> Unit,
    onEditReadout: (String) -> Unit,
    routeAnalysisProject: EventProjectFile? = null
) {
    val routeStatuses = remember(routeAnalysisProject) { routeAnalysisProject?.let(DesktopClassicRouteAnalysis::statuses).orEmpty() }
    val routeLengths = remember(routeAnalysisProject) { routeAnalysisProject?.let(DesktopClassicRouteAnalysis::projection).orEmpty() }
    val horizontalScrollState = rememberScrollState()
    val tableWidth = fixedTableWidth(ResultTableColumns)
    val groupedResults = results.groupBy { it.categoryId to it.categoryName }

    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        publicationNotice?.let { notice ->
            Text(
                text = notice,
                color = DesktopPalette.Warning,
                fontSize = 13.sp,
                fontWeight = FontWeight.SemiBold
            )
        }
        Box(modifier = Modifier.fillMaxWidth().horizontalScroll(horizontalScrollState)) {
            Column(
                modifier = Modifier.width(tableWidth),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                groupedResults.forEach { (category, categoryResults) ->
                    ResultCategoryHeader(category.second, categoryResults.size, tableWidth,
                        categoryResults.firstNotNullOfOrNull { routeLengths[it.id] }?.categoryHeadingSuffix.orEmpty())
                    FixedDetailHeaderRow(ResultTableColumns)
                    categoryResults.forEach { result ->
                        ResultDetailRow(result, onUpdateReadoutStatus, onEditReadout)
                        routeAnalysisProject?.let {
                            Text("Estimated effective route length: ${routeStatuses[result.id] ?: "Not calculated"}", fontSize = 12.sp)
                        }
                    }
                }
            }
        }
        HorizontalScrollbar(
            adapter = rememberScrollbarAdapter(horizontalScrollState),
            modifier = Modifier.fillMaxWidth()
        )
    }
}

/** Shows the competition category for the result rows that follow. */
@Composable
private fun ResultCategoryHeader(
    categoryName: String,
    resultCount: Int,
    tableWidth: Dp,
    idealRouteSuffix: String = ""
) {
    Text(
        text = "$categoryName ($resultCount)$idealRouteSuffix",
        fontWeight = FontWeight.Bold,
        modifier = Modifier
            .width(tableWidth)
            .background(MaterialTheme.colors.onSurface.copy(alpha = 0.06f))
            .padding(horizontal = 8.dp, vertical = 6.dp)
    )
}

/** Shows one ranked result row with explicit manual status editing. */
@Composable
private fun ResultDetailRow(
    result: EventResultDetails,
    onUpdateReadoutStatus: (String, ResultStatus) -> Unit,
    onEditReadout: (String) -> Unit
) {
    val textColor = if (result.hasWarning) DesktopPalette.Error else DesktopPalette.Black
    Row(
        modifier = Modifier.width(fixedTableWidth(ResultTableColumns)),
        horizontalArrangement = Arrangement.spacedBy(TableColumnGap),
        verticalAlignment = Alignment.CenterVertically
    ) {
        FixedTableText(result.placeText, ResultTableColumns[0].width, color = textColor)
        FixedTableText(result.competitorName, ResultTableColumns[1].width, color = textColor)
        ResultStatusPicker(
            selectedStatus = result.resultStatus,
            onStatusSelected = { status ->
                if (status != result.resultStatus) {
                    onUpdateReadoutStatus(result.id, status)
                }
            },
            modifier = Modifier.width(ResultTableColumns[2].width)
        )
        FixedTableText(result.pointsText, ResultTableColumns[3].width, color = textColor)
        FixedTableText(result.runTimeText, ResultTableColumns[4].width, color = textColor)
        FixedTableText(result.punchCodesText, ResultTableColumns[5].width, color = textColor)
        Button(
            onClick = { onEditReadout(result.id) },
            modifier = Modifier.width(ResultTableColumns[6].width)
        ) {
            ButtonLabel("Edit")
        }
    }
}

/** Shows derived National and Regional championship awards by category. */
@Composable
private fun AwardsResultDetailsPanel(awards: EventAwardDetails) {
    val horizontalScrollState = rememberScrollState()
    val tableWidth = fixedTableWidth(AwardTableColumns)

    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        awards.publicationNotice?.let { notice ->
            Text(
                text = notice,
                color = DesktopPalette.Warning,
                fontSize = 13.sp,
                fontWeight = FontWeight.SemiBold
            )
        }
        if (!awards.hasAwards) {
            Text(
                text = if (awards.publicationNotice == null) {
                    "Awards are not shown for practice races."
                } else if (awards.awardScopes.isEmpty()) {
                    "Awards are shown for National, Regional, or combined National/Regional races."
                } else {
                    "No ${awards.awardScopes.joinToString(" or ") { it.displayLabel }} winners are available from the current results."
                },
                color = DesktopPalette.Black,
                fontSize = 13.sp
            )
            return
        }
        Box(modifier = Modifier.fillMaxWidth().horizontalScroll(horizontalScrollState)) {
            Column(
                modifier = Modifier.width(tableWidth),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                awards.categories.forEach { category ->
                    val awardCount = awards.awardScopes.sumOf { scope -> category.awardsForScope(scope).size }
                    ResultCategoryHeader(category.categoryName, awardCount, tableWidth)
                    awards.awardScopes.forEach { scope ->
                        AwardScopeRows(scope.displayLabel, category.awardsForScope(scope))
                    }
                }
            }
        }
        HorizontalScrollbar(
            adapter = rememberScrollbarAdapter(horizontalScrollState),
            modifier = Modifier.fillMaxWidth()
        )
    }
}

@Composable
