@Composable
private fun ReadoutPunchEditRow(
    punchNumber: Int,
    punch: DesktopReadoutPunchEditDraft,
    controls: List<EventControl>,
    canMoveUp: Boolean,
    canMoveDown: Boolean,
    timeMode: DesktopReadoutPunchTimeMode,
    isTimeError: Boolean,
    onControlSelected: (String?) -> Unit,
    onTimeChanged: (String) -> Unit,
    onMoveUp: () -> Unit,
    onMoveDown: () -> Unit,
    onDelete: () -> Unit,
    onCommit: () -> Unit
) {
    val timeText = when (timeMode) {
        DesktopReadoutPunchTimeMode.ELAPSED -> punch.elapsedTime
        DesktopReadoutPunchTimeMode.SI -> punch.siTime
    }
    Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically) {
        FixedTableText(punchNumber.toString(), 32.dp, DesktopPalette.Black)
        ReadoutControlPicker(
            selectedControlId = punch.controlId,
            controls = controls,
            onControlSelected = onControlSelected,
            modifier = Modifier.width(112.dp),
            emptySelectionText = punch.controlText
        )
        TextField(
            value = timeText,
            onValueChange = onTimeChanged,
            singleLine = true,
            isError = isTimeError,
            modifier = Modifier
                .width(92.dp)
                .commitOnEnter(onCommit)
        )
        Button(onClick = onMoveUp, enabled = canMoveUp, modifier = Modifier.width(48.dp), contentPadding = PaddingValues(horizontal = 4.dp)) {
            Text("Up", fontSize = 12.sp)
        }
        Button(onClick = onMoveDown, enabled = canMoveDown, modifier = Modifier.width(56.dp), contentPadding = PaddingValues(horizontal = 4.dp)) {
            Text("Down", fontSize = 12.sp)
        }
        Button(onClick = onDelete, modifier = Modifier.width(68.dp), contentPadding = PaddingValues(horizontal = 4.dp)) {
            Text("Delete", fontSize = 12.sp)
        }
    }
}

@Composable
private fun ReadoutControlPicker(
    selectedControlId: String?,
    controls: List<EventControl>,
    onControlSelected: (String?) -> Unit,
    modifier: Modifier = Modifier,
    emptySelectionText: String = "No controls available"
) {
    var expanded by remember { mutableStateOf(false) }
    val selectedControl = controls.firstOrNull { it.id == selectedControlId }
    val selectedText = selectedControl?.publicDisplayLabel() ?: emptySelectionText

    Box(modifier = modifier) {
        Button(
            onClick = { expanded = true },
            enabled = controls.isNotEmpty(),
            modifier = Modifier.fillMaxWidth()
        ) {
            Text(selectedText)
        }
        DropdownMenu(
            expanded = expanded,
            onDismissRequest = { expanded = false }
        ) {
            controls.forEach { control ->
                DropdownMenuItem(
                    onClick = {
                        expanded = false
                        onControlSelected(control.id)
                    }
                ) {
                    Text("${control.publicDisplayLabel()} (${control.siCode})")
                }
            }
        }
    }
}

/** Shows a compact competitor selector with an explicit unmatched-readout option. */
@Composable
private fun CompetitorPicker(
    selectedCompetitorId: String?,
    competitors: List<EventCompetitorDetails>,
    onCompetitorSelected: (String?) -> Unit,
    modifier: Modifier = Modifier
) {
    var expanded by remember { mutableStateOf(false) }
    val selectedCompetitorName = competitors.firstOrNull { it.id == selectedCompetitorId }?.fullName ?: "Unmatched"

    Box(modifier = modifier) {
        Button(
            onClick = { expanded = true },
            modifier = Modifier.fillMaxWidth()
        ) {
            Text(selectedCompetitorName)
        }
        DropdownMenu(
            expanded = expanded,
            onDismissRequest = { expanded = false }
        ) {
            DropdownMenuItem(
                onClick = {
                    expanded = false
                    onCompetitorSelected(null)
                }
            ) {
                Text("Unmatched")
            }
            competitors.forEach { competitor ->
                DropdownMenuItem(
                    onClick = {
                        expanded = false
                        onCompetitorSelected(competitor.id)
