@Composable
private fun EditableTableTextField(
    value: String,
    onValueChange: (String) -> Unit,
    width: Dp,
    label: String,
    warningText: String,
    textColor: Color,
    textStyle: androidx.compose.ui.text.TextStyle,
    onCommit: () -> Unit
) {
    ControlWarningTooltip(warningText) {
        TextField(
            value = value,
            onValueChange = onValueChange,
            modifier = Modifier
                .width(width)
