/** Shows a compact category selector with an explicit unassigned option. */
@Composable
private fun CategoryPicker(
    selectedCategoryId: String?,
    categories: List<EventCategoryDetails>,
    onCategorySelected: (String?) -> Unit,
    modifier: Modifier = Modifier,
    textColor: Color = Color.White
) {
    var expanded by remember { mutableStateOf(false) }
    val selectedCategoryName = categories.firstOrNull { it.id == selectedCategoryId }?.name ?: "Unassigned"

    Box(modifier = modifier) {
        Button(
            onClick = { expanded = true },
            modifier = Modifier.fillMaxWidth(),
            colors = ButtonDefaults.buttonColors(contentColor = textColor)
        ) {
            Text(selectedCategoryName)
        }
        DropdownMenu(
            expanded = expanded,
            onDismissRequest = { expanded = false }
        ) {
            DropdownMenuItem(
                onClick = {
                    expanded = false
                    onCategorySelected(null)
                }
            ) {
                Text("Unassigned")
            }
            categories.forEach { category ->
                DropdownMenuItem(
                    onClick = {
                        expanded = false
                        onCategorySelected(category.id)
                    }
                ) {
                    Text(category.name)
                }
            }
        }
    }
}

/** Shows editable global logical controls backed by shared Race File editing rules. */
@Composable
private fun ControlDetailsPanel(
    controls: List<EventControlDetails>,
    categories: List<EventCategoryData>,
    raceType: RaceType,
    onUpdateControl: (String, String, String, ControlPointType, Boolean, String, String) -> Unit,
    onAddControl: (String, String, ControlPointType, Boolean, String, String) -> Boolean,
    onRemoveControl: (String) -> Unit
) {
    val horizontalScrollState = rememberScrollState()
    val tableWidth = fixedTableWidth(ControlTableColumns)
    val orderedControls = remember(controls, raceType) { controls.customaryDisplayOrder(raceType) }
    val warningReasonsByControlId = remember(controls, categories) {
        controlSuspicionReasonsByControlId(controls, categories)
    }
    var siCodeDraft by remember { mutableStateOf("") }
    var typeDraft by remember { mutableStateOf(ControlPointType.CONTROL) }
    var publicLabelDraft by remember { mutableStateOf("") }
    var notesDraft by remember { mutableStateOf("") }
    fun addControl() {
        val didAdd = onAddControl("", siCodeDraft, typeDraft, typeDraft.defaultScored(), publicLabelDraft, notesDraft)
        if (didAdd) {
            siCodeDraft = ""
            typeDraft = ControlPointType.CONTROL
            publicLabelDraft = ""
            notesDraft = ""
        }
    }
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        ControlStatsRow(
            controls = controls,
            raceType = raceType,
            warningReasonsByControlId = warningReasonsByControlId
        )
        Text(
            text = "Finish stations are read automatically from the SI card. Do not add the finish station's SI code as a Fox, Beacon, or Control.",
            color = DesktopPalette.Disconnected,
            fontSize = 13.sp
        )
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(TableColumnGap),
            verticalAlignment = Alignment.Top
        ) {
            Button(
                onClick = ::addControl,
                modifier = fixedActionRailModifier(),
                enabled = siCodeDraft.isNotBlank()
            ) {
                ButtonLabel("Add")
            }
            Box(modifier = Modifier.weight(1f).horizontalScroll(horizontalScrollState)) {
                Column(
                    modifier = Modifier.width(tableWidth),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    ControlAddRow(
                        siCodeDraft = siCodeDraft,
                        onSiCodeChange = { siCodeDraft = it },
                        typeDraft = typeDraft,
                        raceType = raceType,
                        onTypeChange = { typeDraft = it },
                        publicLabelDraft = publicLabelDraft,
                        onPublicLabelChange = { publicLabelDraft = it },
                        notesDraft = notesDraft,
                        onNotesChange = { notesDraft = it },
                        onCommit = {
                            if (siCodeDraft.isNotBlank()) {
                                addControl()
                            }
                        }
                    )
                    FixedDetailHeaderRow(ControlTableColumns, ControlTableColumnHints)
                }
            }
        }
        HorizontalScrollbar(
            adapter = rememberScrollbarAdapter(horizontalScrollState),
            modifier = Modifier.fillMaxWidth()
        )
        Column(
            modifier = Modifier.fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            orderedControls.forEach { control ->
                key(control.id) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(TableColumnGap),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        ControlDeleteButton(control, onRemoveControl)
                        Box(modifier = Modifier.weight(1f).horizontalScroll(horizontalScrollState)) {
                            val warningReasons = warningReasonsByControlId[control.id].orEmpty()
                            ControlDetailRow(
                                control = control,
                                raceType = raceType,
                                warningReasons = warningReasons,
                                onUpdateControl = onUpdateControl
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun ControlStatsRow(
    controls: List<EventControlDetails>,
    raceType: RaceType,
    warningReasonsByControlId: Map<String, List<String>>
) {
    val unusedControlCount = unusedControlWarningCount(warningReasonsByControlId)
    val items = controlStatsItems(controls, raceType) + ControlStatsItem(
        label = "Unused",
        count = unusedControlCount,
        isCompliant = unusedControlCount == 0
    )
    val firstWarningLabel = items.firstOrNull { !it.isCompliant }?.label
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(18.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        items.forEach { item ->
            ControlStatsText(
                label = item.label,
                count = item.count,
                isCompliant = item.isCompliant,
                showWarningPrefix = item.label == firstWarningLabel
            )
        }
    }
}

@Composable
private fun ControlStatsText(
    label: String,
    count: Int,
    isCompliant: Boolean,
    showWarningPrefix: Boolean
) {
    Text(
        text = "${if (showWarningPrefix) "WARNING: " else ""}$label: $count",
        color = if (isCompliant) ControlStatsOkColor else DesktopPalette.Error,
        fontSize = 13.sp,
        fontWeight = FontWeight.Bold
    )
}

private fun controlStatsItems(controls: List<EventControlDetails>, raceType: RaceType): List<ControlStatsItem> {
    val counts = ControlRoleCounts.from(controls.map { it.type })
    return when (raceType) {
        RaceType.SPRINT -> {
            val loopGroups = SprintLoopControlGroups.from(controls)
            listOf(
                ControlStatsItem("Slow-loop Foxes", loopGroups.slowLoopFoxes.size, loopGroups.slowLoopFoxes.size == 5),
                ControlStatsItem("Fast-loop Foxes", loopGroups.fastLoopFoxes.size, loopGroups.fastLoopFoxes.size == 5),
                ControlStatsItem("Beacons", counts.beacons, counts.beacons == 1),
                ControlStatsItem("Spectators", counts.spectators, counts.spectators <= 1)
            )
        }
        RaceType.CLASSIC,
        RaceType.SHORT -> listOf(
            ControlStatsItem("Foxes", counts.foxes, counts.foxes == 5),
            ControlStatsItem("Beacons", counts.beacons, counts.beacons == 1)
        )
        RaceType.FOXORING -> listOf(
            ControlStatsItem("Foxes", counts.foxes, counts.foxes in 4..12),
            ControlStatsItem("Beacons", counts.beacons, counts.beacons == 1)
        )
        RaceType.ORIENTEERING -> listOf(
            ControlStatsItem("Controls", counts.foxes, counts.foxes > 0)
        )
    }
}

private fun List<EventControlDetails>.customaryDisplayOrder(raceType: RaceType): List<EventControlDetails> =
    when (raceType) {
        RaceType.SPRINT -> {
            val groups = SprintLoopControlGroups.from(this)
            sortedWith(
                compareBy<EventControlDetails> { SprintControlDisplaySlot.forControl(it, groups) }
                    .thenBy { it.siCode }
                    .thenBy { it.publicDisplayLabel() }
            )
        }
        RaceType.CLASSIC,
        RaceType.SHORT,
        RaceType.FOXORING -> sortedWith(
            compareBy<EventControlDetails> {
                when (it.type) {
                    ControlPointType.CONTROL -> 0
                    ControlPointType.SEPARATOR -> 1
                    ControlPointType.BEACON -> 2
                }
            }
                .thenBy { it.siCode }
                .thenBy { it.publicDisplayLabel() }
        )
        RaceType.ORIENTEERING -> sortedWith(compareBy<EventControlDetails> { it.siCode }.thenBy { it.publicDisplayLabel() })
    }

private fun EventControlDetails.sprintLoopFromLabel(): SprintLoop? =
    publicLabel.trim().takeIf { it.isNotEmpty() }?.sprintLoopLabel()
        ?: label.trim().takeIf { it.isNotEmpty() }?.sprintLoopLabel()

private fun String.sprintLoopLabel(): SprintLoop? =
    when {
        sprintFastNumber() != null || trim().uppercase().contains("FAST") -> SprintLoop.Fast
        sprintSlowNumber() != null -> SprintLoop.Slow
        else -> null
    }

private fun String.sprintDisplaySlot(): SprintControlDisplaySlot? {
    val normalized = trim().uppercase()
    return when {
        normalized in setOf("S", "SP", "SPEC", "SPECTATOR", "SEP", "SEPARATOR") ->
            SprintControlDisplaySlot(1, 0)
        normalized in setOf("B", "BB", "M", "MO", "BEACON", "FINISH BEACON") ->
            SprintControlDisplaySlot(3, 0)
        sprintFastNumber() != null -> SprintControlDisplaySlot(2, sprintFastNumber() ?: 0)
        sprintSlowNumber() != null -> SprintControlDisplaySlot(0, sprintSlowNumber() ?: 0)
        normalized.contains("FAST") -> SprintControlDisplaySlot(2, Int.MAX_VALUE)
        else -> null
    }
}

private fun String.sprintSlowNumber(): Int? {
    return DesktopCoursePointLabelClassifier.sprintSlowFoxNumber(this)
}

private fun String.sprintFastNumber(): Int? {
    return DesktopCoursePointLabelClassifier.sprintFastFoxNumber(this)
}

@Composable
private fun CourseToolsSectionWorkspaceContent(
    section: DesktopSection,
    projectFile: EventProjectFile?,
    protectedCourseInfoByCategoryId: Map<String, ProtectedCourseInfo>
) {
    when (section) {
        DesktopSection.CourseReport -> projectFile?.let {
            CourseReportPanel(
                projectFile = it,
                protectedCourseInfoByCategoryId = protectedCourseInfoByCategoryId
            )
        }
        DesktopSection.KmlMoveCourse -> KmlMoveCoursePanel()
        DesktopSection.KmlCreateCourse -> KmlCreateCoursePanel(projectFile)
        DesktopSection.Kml2dGraphic -> Kml2dGraphicPanel()
        DesktopSection.KmlRouteGenerator -> KmlRouteGeneratorPanel()
        else -> Unit
    }
}

@Composable
private fun CourseReportPanel(
    projectFile: EventProjectFile,
    protectedCourseInfoByCategoryId: Map<String, ProtectedCourseInfo>
) {
    var statusText by remember(projectFile.raceData.race.id) { mutableStateOf<String?>(null) }

    Column(
        verticalArrangement = Arrangement.spacedBy(14.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Text(
            text = "Course Report",
            color = DesktopPalette.Black,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold
        )
        Text(
            text = "Exports one row per unique set of SI controls. Control numbers are listed least-to-greatest and identical sets are combined; courses are numbered longest-first, with distance in kilometers and climb in meters.",
            color = DesktopPalette.Black,
            fontSize = 14.sp
        )
        val reportRows = DesktopCourseReportCsv.rows(
            projectFile = projectFile,
            protectedCourseInfoByCategoryId = protectedCourseInfoByCategoryId
        )
        if (reportRows.isEmpty()) {
            Text(
                text = "Assign SI controls to at least one category before exporting a Course Report.",
                color = DesktopPalette.Black,
                fontSize = 14.sp
            )
            return@Column
        }
        Button(
            onClick = {
                DesktopFileDialogs.chooseExportCsv(
                    title = "Export Course Report CSV",
                    eventName = projectFile.raceData.race.name,
                    suffix = "course report"
                )?.let { path ->
                    runCatching {
                        DesktopProjectFiles.exportCourseReportCsv(
                            path = path,
                            projectFile = projectFile,
                            protectedCourseInfoByCategoryId = protectedCourseInfoByCategoryId
                        )
                    }.onSuccess {
                        statusText = "Exported ${path.fileName} with ${reportRows.size} unique control sets."
                    }.onFailure { error ->
                        statusText = "Course Report export failed: ${error.message ?: error::class.simpleName}"
                    }
                }
            }
        ) {
            ButtonLabel("Export Course Report CSV...")
        }
        statusText?.let { text ->
            Text(
                text = text,
                color = if (text.startsWith("Course Report export failed")) {
                    DesktopPalette.Error
                } else {
                    DesktopPalette.Disconnected
                },
                fontSize = 13.sp
            )
        }
    }
}

@Composable
private fun KmlMoveCoursePanel() {
    var selectedPath by remember { mutableStateOf<Path?>(null) }
    var latitudeDraft by remember { mutableStateOf("") }
    var longitudeDraft by remember { mutableStateOf("") }
    var statusText by remember { mutableStateOf<String?>(null) }
    val parsedLatitude = latitudeDraft.trim().toDoubleOrNull()
    val parsedLongitude = longitudeDraft.trim().toDoubleOrNull()
    val canApply = selectedPath != null &&
        parsedLatitude != null &&
        parsedLatitude.isValidLatitude() &&
        parsedLongitude != null &&
        parsedLongitude.isValidLongitude()

    fun chooseFile() {
        DesktopFileDialogs.chooseKmlToolsFile()?.let { path ->
            selectedPath = path
            statusText = null
        }
    }

    fun applyMoveCourse() {
        val path = selectedPath ?: return
        val latitude = parsedLatitude ?: return
        val longitude = parsedLongitude ?: return
        runCatching {
            DesktopKmlTools.moveCourse(
                sourcePath = path,
                newStart = DesktopKmlToolsPoint(latitude = latitude, longitude = longitude)
            )
        }.onSuccess { result ->
            val folderStatus = openKmlToolsOutputFolder(result.outputPath).orEmpty()
            statusText = "Created ${result.outputPath.fileName}; moved ${result.translatedCoordinateCount} coordinates.$folderStatus"
        }.onFailure { error ->
            statusText = "Move Course failed: ${error.message ?: error::class.simpleName}"
        }
    }

    Column(
        verticalArrangement = Arrangement.spacedBy(14.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Text(
            text = "Move Course",
            color = DesktopPalette.Black,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold
        )
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(onClick = ::chooseFile) {
                ButtonLabel("Choose KML/KMZ...")
            }
            Text(
                text = selectedPath?.fileName?.toString() ?: "No file selected",
                color = DesktopPalette.Black,
                fontSize = 13.sp
            )
        }
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            TextField(
                value = latitudeDraft,
                onValueChange = { latitudeDraft = it },
                label = { Text("New Start Latitude") },
                singleLine = true,
                modifier = Modifier
                    .width(180.dp)
                    .commitOnEnter(::applyMoveCourse)
            )
            TextField(
                value = longitudeDraft,
                onValueChange = { longitudeDraft = it },
                label = { Text("New Start Longitude") },
                singleLine = true,
                modifier = Modifier
                    .width(180.dp)
                    .commitOnEnter(::applyMoveCourse)
            )
            Button(
                onClick = ::applyMoveCourse,
                enabled = canApply
            ) {
                ButtonLabel("Apply")
            }
        }
        statusText?.let { text ->
            Text(
                text = text,
                color = if (text.startsWith("Move Course failed")) DesktopPalette.Error else DesktopPalette.Disconnected,
                fontSize = 13.sp
            )
        }
    }
}

@Composable
private fun KmlCreateCoursePanel(projectFile: EventProjectFile?) {
    val defaultEventType = projectFile
        ?.raceData
        ?.race
        ?.raceType
        ?.takeIf { it in DesktopCreateCourseKml.supportedEventTypes }
        ?: RaceType.CLASSIC
    var selectedEventType by remember(projectFile?.raceData?.race?.id) { mutableStateOf(defaultEventType) }
    var isEventTypeMenuExpanded by remember { mutableStateOf(false) }
    var selectedPath by remember { mutableStateOf<Path?>(null) }
    var latitudeDraft by remember { mutableStateOf("") }
    var longitudeDraft by remember { mutableStateOf("") }
    var statusText by remember { mutableStateOf<String?>(null) }
    val parsedLatitude = latitudeDraft.trim().toDoubleOrNull()
    val parsedLongitude = longitudeDraft.trim().toDoubleOrNull()
    val canCreate = selectedPath != null &&
        parsedLatitude != null &&
        parsedLatitude.isValidLatitude() &&
        parsedLongitude != null &&
        parsedLongitude.isValidLongitude()

    fun chooseOutputFile() {
        DesktopFileDialogs.chooseExportCreateCourseKml(
            defaultFileName = DesktopCreateCourseKml.defaultFileName(
                eventName = projectFile?.raceData?.race?.name,
                eventType = selectedEventType
            )
        )?.let { path ->
            selectedPath = path
            statusText = null
        }
    }

    fun createCourse() {
        val path = selectedPath ?: return
        val latitude = parsedLatitude ?: return
        val longitude = parsedLongitude ?: return
        runCatching {
            DesktopCreateCourseKml.create(
                outputPath = path,
                eventType = selectedEventType,
                center = DesktopKmlToolsPoint(latitude = latitude, longitude = longitude),
                projectFile = projectFile
            )
        }.onSuccess { result ->
            val reuseText = if (result.reusedControlCount > 0) {
                " reused ${result.reusedControlCount} Race File controls."
            } else {
                " no Race File controls reused."
            }
            val folderStatus = openKmlToolsOutputFolder(result.outputPath).orEmpty()
            statusText = "Created ${result.outputPath.fileName}; wrote ${result.pointCount} ${result.eventType.createCourseTypeLabel()} course points;$reuseText$folderStatus"
        }.onFailure { error ->
            statusText = "Create Course failed: ${error.message ?: error::class.simpleName}"
        }
    }

    Column(
        verticalArrangement = Arrangement.spacedBy(14.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Text(
            text = "Create Course",
            color = DesktopPalette.Black,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold
        )
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box {
                Button(onClick = { isEventTypeMenuExpanded = true }) {
                    ButtonLabel(selectedEventType.createCourseTypeLabel())
                }
                DropdownMenu(
                    expanded = isEventTypeMenuExpanded,
                    onDismissRequest = { isEventTypeMenuExpanded = false }
                ) {
                    DesktopCreateCourseKml.supportedEventTypes.forEach { eventType ->
                        DropdownMenuItem(
                            onClick = {
                                selectedEventType = eventType
                                isEventTypeMenuExpanded = false
                                statusText = null
                            }
                        ) {
                            Text(eventType.createCourseTypeLabel())
                        }
                    }
                }
            }
            Button(onClick = ::chooseOutputFile) {
                ButtonLabel("Choose Output...")
            }
            Text(
                text = selectedPath?.fileName?.toString() ?: "No file selected",
                color = DesktopPalette.Black,
                fontSize = 13.sp
            )
        }
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            TextField(
                value = latitudeDraft,
                onValueChange = { latitudeDraft = it },
                label = { Text("Location Latitude") },
                singleLine = true,
                modifier = Modifier
                    .width(180.dp)
                    .commitOnEnter(::createCourse)
            )
            TextField(
                value = longitudeDraft,
                onValueChange = { longitudeDraft = it },
                label = { Text("Location Longitude") },
                singleLine = true,
                modifier = Modifier
                    .width(180.dp)
                    .commitOnEnter(::createCourse)
            )
            Button(
                onClick = ::createCourse,
                enabled = canCreate
            ) {
                ButtonLabel("Create")
            }
        }
        statusText?.let { text ->
            Text(
                text = text,
                color = if (text.startsWith("Create Course failed")) DesktopPalette.Error else DesktopPalette.Disconnected,
                fontSize = 13.sp
            )
        }
    }
}

@Composable
private fun Kml2dGraphicPanel() {
    var selectedPath by remember { mutableStateOf<Path?>(null) }
    var result by remember { mutableStateOf<DesktopCourseGraphicResult?>(null) }
    var statusText by remember { mutableStateOf<String?>(null) }
    var isGenerating by remember { mutableStateOf(false) }
    val generationScope = rememberCoroutineScope()
    val title = "2D Graphic"

    fun chooseFile() {
        if (isGenerating) return
        DesktopFileDialogs.chooseKmlToolsFile()?.let { path ->
            selectedPath = path
            result = null
            statusText = null
            isGenerating = true
            generationScope.launch {
                try {
                    delay(100)
                    val generated = withContext(Dispatchers.Default) {
                        DesktopCourseGraphic.generate(path)
                    }
                    result = generated
                    val folderStatus = openKmlToolsOutputFolder(generated.outputPaths.pngPath).orEmpty()
                    statusText = "Created ${generated.outputPaths.pngPath.fileName}, " +
                        "${generated.outputPaths.jpgPath.fileName}, and ${generated.outputPaths.pdfPath.fileName}; " +
                        "drew ${generated.visiblePointCount} visible points, ${generated.visibleLineStringCount} visible LineStrings, " +
                        "and ${generated.visiblePolygonCount} visible Polygons; " +
                        "ignored ${generated.hiddenObjectCount} hidden objects.$folderStatus"
                } catch (error: Throwable) {
                    result = null
                    statusText = "$title failed: ${error.message ?: error::class.simpleName}"
                } finally {
                    isGenerating = false
                }
            }
        }
    }

    Column(
        verticalArrangement = Arrangement.spacedBy(14.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Text(
            text = title,
            color = DesktopPalette.Black,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold
        )
        Text(
            text = "Choose a KML/KMZ layout file. Radio-Oracle writes PNG, JPG, and PDF graphics beside the input file, ignores hidden objects, and orients the depiction to magnetic north.",
            color = DesktopPalette.Black,
            fontSize = 13.sp
        )
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(
                onClick = ::chooseFile,
                enabled = !isGenerating
            ) {
                ButtonLabel("Choose KML/KMZ...")
            }
            Text(
                text = selectedPath?.fileName?.toString() ?: "No file selected",
                color = DesktopPalette.Black,
                fontSize = 13.sp
            )
        }
        statusText?.let { text ->
            Text(
                text = text,
                color = if (text.startsWith("$title failed")) DesktopPalette.Error else DesktopPalette.Disconnected,
                fontSize = 13.sp
            )
        }
        result?.routeMap?.let { routeMap ->
            CourseAnalysisRouteMap(
                routeMap = routeMap,
                mapWidth = 620.dp,
                mapHeight = 420.dp,
                showWaypointLabels = true,
                showLineStringLabels = true
            )
        }
    }
    if (isGenerating) {
        IndeterminateProgressDialog(
            title = "Generating 2D Graphic",
            message = "Reading visible KML/KMZ points and LineStrings, rotating to magnetic north, and writing PNG, JPG, and PDF outputs."
        )
    }
}

private fun openKmlToolsOutputFolder(path: Path): String? =
    runCatching {
        val directory = path.parent ?: Path.of(".").toAbsolutePath()
        if (!Desktop.isDesktopSupported()) {
            error("Opening folders is not supported on this system.")
        }
        val desktop = Desktop.getDesktop()
        if (!desktop.isSupported(Desktop.Action.OPEN)) {
            error("Opening folders is not supported on this system.")
        }
        desktop.open(directory.toFile())
    }.exceptionOrNull()?.let { error ->
        " Could not open output folder: ${error.message ?: error::class.simpleName}"
    }

@Composable
private fun KmlRouteGeneratorPanel() {
    var selectedPath by remember { mutableStateOf<Path?>(null) }
    var result by remember { mutableStateOf<ClassicCourseGeneratorResult?>(null) }
    var statusText by remember { mutableStateOf<String?>(null) }
    var isGenerating by remember { mutableStateOf(false) }
    var activeMode by remember { mutableStateOf<RouteGeneratorMode?>(null) }
    var pendingTypeChoice by remember { mutableStateOf<RouteGeneratorTypeChoice?>(null) }
    val generationScope = rememberCoroutineScope()
    val title = "Route Generator"

    fun generationStatus(generated: ClassicCourseGeneratorResult): String {
        val elevationStatus = when {
            generated.missingElevationPointCount == 0 && generated.elevationResolvedPointCount > 0 ->
                " Filled ${generated.elevationResolvedPointCount} missing elevations from the local cache."
            generated.missingElevationPointCount > 0 ->
                " ${generated.missingElevationPointCount} point elevations are still missing; category matches require complete elevations."
            else -> ""
        }
        return "Generated ${generated.rows.size} ideal ${generated.formatLabel} route combinations from ${generated.foxes.size} foxes.$elevationStatus"
    }

    fun startGeneration(
        path: Path,
        courseData: DesktopCourseKmlData,
        mode: RouteGeneratorMode
    ) {
        if (isGenerating) return
        isGenerating = true
        activeMode = mode
        result = null
        statusText = null
        generationScope.launch {
            try {
                delay(100)
                val generated = withContext(Dispatchers.Default) {
                    mode.generateResult(path, courseData)
                }
                result = generated
                statusText = generationStatus(generated)
            } catch (error: Throwable) {
                result = null
                statusText = "${mode.title} failed: ${error.message ?: error::class.simpleName}"
            } finally {
                isGenerating = false
                activeMode = null
            }
        }
    }

    fun chooseFile() {
        if (isGenerating) return
        DesktopFileDialogs.chooseKmlToolsFile()?.let { path ->
            selectedPath = path
            result = null
            statusText = null
            pendingTypeChoice = null
            isGenerating = true
            activeMode = null
            generationScope.launch {
                try {
                    delay(100)
                    val courseData = withContext(Dispatchers.IO) {
                        DesktopCourseFileReader.read(path)
                    }
                    val detectedType = DesktopCourseFormatDetector.detectedGeneratorRaceType(
                        sourceName = path.fileName.toString(),
                        courseData = courseData
                    )
                    if (detectedType == null) {
                        val inferredTypes = DesktopCourseFormatDetector.inferredRaceTypes(
                            path.fileName.toString(),
                            courseData
                        ).distinct().filter { it in DesktopCourseFormatDetector.supportedGeneratorRaceTypes }
                        pendingTypeChoice = RouteGeneratorTypeChoice(
                            path = path,
                            courseData = courseData,
                            inferredTypes = inferredTypes
                        )
                        statusText = "Choose a route type for ${path.fileName}."
                        return@launch
                    }
                    val mode = routeGeneratorMode(detectedType)
                    activeMode = mode
                    val generated = withContext(Dispatchers.Default) {
                        mode.generateResult(path, courseData)
                    }
                    result = generated
                    statusText = generationStatus(generated)
                } catch (error: Throwable) {
                    result = null
                    statusText = "$title failed: ${error.message ?: error::class.simpleName}"
                } finally {
                    isGenerating = false
                    activeMode = null
                }
            }
        }
    }

    fun exportResults() {
        val generated = result ?: return
        DesktopFileDialogs.chooseExportCourseGeneratorPdf(
            title = "Export ${generated.generatorTitle} PDF",
            defaultFileName = routeGeneratorMode(generated).defaultPdfFileName(generated)
        )?.let { path ->
            runCatching {
                routeGeneratorMode(generated).exportPdfAndKml(path, generated)
            }.onSuccess { exports ->
                statusText = "Exported ${exports.pdfPath.fileName} and ${exports.kmlPath.fileName}"
            }.onFailure { error ->
                statusText = "${generated.generatorTitle} export failed: ${error.message ?: error::class.simpleName}"
            }
        }
    }

    Column(
        verticalArrangement = Arrangement.spacedBy(14.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Text(
            text = title,
            color = DesktopPalette.Black,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold
        )
        Text(
            text = "Choose a KML/KMZ course-points file. If the file name or course elements identify Classic, Foxoring, or Sprint, generation starts immediately. If the type is ambiguous, choose the route type when prompted.",
            color = DesktopPalette.Black,
            fontSize = 13.sp
        )
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(
                onClick = ::chooseFile,
                enabled = !isGenerating
            ) {
                ButtonLabel("Choose KML/KMZ...")
            }
            Button(
                onClick = ::exportResults,
                enabled = result != null && !isGenerating
            ) {
                ButtonLabel("Export PDF/KML...")
            }
            Text(
                text = selectedPath?.fileName?.toString() ?: "No file selected",
                color = DesktopPalette.Black,
                fontSize = 13.sp
            )
        }
        statusText?.let { text ->
            Text(
                text = text,
                color = if (text.startsWith(title) && text.contains("failed")) {
                    DesktopPalette.Error
                } else {
                    DesktopPalette.Disconnected
                },
                fontSize = 13.sp
            )
        }
        result?.let { generated ->
            ClassicCourseGeneratorResultView(generated)
        }
    }
    if (isGenerating) {
        val mode = activeMode
        IndeterminateProgressDialog(
            title = mode?.progressTitle ?: "Opening Route Generator file",
            message = mode?.progressMessage ?: "Reading course points and identifying the route generator type."
        )
    }
    pendingTypeChoice?.let { choice ->
        RouteGeneratorTypeChoiceDialog(
            choice = choice,
            onChoose = { eventType ->
                pendingTypeChoice = null
                statusText = null
                startGeneration(choice.path, choice.courseData, routeGeneratorMode(eventType))
            },
            onCancel = {
                pendingTypeChoice = null
                statusText = "Route generation canceled."
            }
        )
    }
}

private data class RouteGeneratorMode(
    val raceType: RaceType,
    val title: String,
    val progressTitle: String,
    val progressMessage: String,
    val generateResult: (Path, DesktopCourseKmlData) -> ClassicCourseGeneratorResult,
    val defaultPdfFileName: (ClassicCourseGeneratorResult) -> String,
    val exportPdfAndKml: (Path, ClassicCourseGeneratorResult) -> ClassicCourseGeneratorExportPaths
)

private data class RouteGeneratorTypeChoice(
    val path: Path,
    val courseData: DesktopCourseKmlData,
    val inferredTypes: List<RaceType>
)

private fun routeGeneratorMode(raceType: RaceType): RouteGeneratorMode =
    when (raceType) {
        RaceType.FOXORING -> RouteGeneratorMode(
            raceType = RaceType.FOXORING,
            title = "Foxoring Route Generator",
            progressTitle = "Generating Foxoring routes",
            progressMessage = "Exhaustively calculating Foxoring route combinations, sampled elevations, effective lengths, category matches, and course requirement warnings.",
            generateResult = { path, data -> DesktopFoxoringCourseGenerator.generate(path, data) },
            defaultPdfFileName = DesktopFoxoringCourseGenerator::defaultPdfFileName,
            exportPdfAndKml = DesktopFoxoringCourseGenerator::exportPdfAndKml
        )
        RaceType.SPRINT -> RouteGeneratorMode(
            raceType = RaceType.SPRINT,
            title = "Sprint Route Generator",
            progressTitle = "Generating Sprint routes",
            progressMessage = "Calculating Sprint slow-loop and fast-loop route combinations, sampled elevations, effective lengths, category matches, and recommended route sets.",
            generateResult = { path, data -> DesktopSprintCourseGenerator.generate(path, data) },
            defaultPdfFileName = DesktopSprintCourseGenerator::defaultPdfFileName,
            exportPdfAndKml = DesktopSprintCourseGenerator::exportPdfAndKml
        )
        else -> RouteGeneratorMode(
            raceType = RaceType.CLASSIC,
            title = "Classic Route Generator",
            progressTitle = "Generating Classic routes",
            progressMessage = "Calculating ideal route combinations, sampled elevations, effective lengths, category matches, and course requirement warnings.",
            generateResult = { path, data -> DesktopClassicCourseGenerator.generate(path, data) },
            defaultPdfFileName = DesktopClassicCourseGenerator::defaultPdfFileName,
            exportPdfAndKml = DesktopClassicCourseGenerator::exportPdfAndKml
        )
    }

private fun routeGeneratorMode(result: ClassicCourseGeneratorResult): RouteGeneratorMode =
    routeGeneratorMode(
        when (result.formatLabel) {
            "Foxoring" -> RaceType.FOXORING
            "Sprint" -> RaceType.SPRINT
            else -> RaceType.CLASSIC
        }
    )

@Composable
private fun RouteGeneratorTypeChoiceDialog(
    choice: RouteGeneratorTypeChoice,
    onChoose: (RaceType) -> Unit,
    onCancel: () -> Unit
) {
    val inferredText = choice.inferredTypes
        .takeIf { it.isNotEmpty() }
        ?.joinToString(" or ") { DesktopCourseFormatDetector.run { it.displayName() } }
        ?: "unknown"
    AlertDialog(
        onDismissRequest = onCancel,
        title = { Text("Choose Route Type") },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Text(
                    text = "Radio-Oracle could not identify one route-generator type for ${choice.path.fileName}.",
                    color = DesktopPalette.Black,
                    fontSize = 13.sp
                )
                Text(
                    text = "Detected type: $inferredText",
                    color = DesktopPalette.Black,
                    fontSize = 13.sp
                )
            }
        },
        confirmButton = {
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                DesktopCourseFormatDetector.supportedGeneratorRaceTypes.forEach { raceType ->
                    Button(onClick = { onChoose(raceType) }) {
                        ButtonLabel(DesktopCourseFormatDetector.run { raceType.displayName() })
                    }
                }
            }
        },
        dismissButton = {
            Button(onClick = onCancel) {
                ButtonLabel("Cancel")
            }
        }
    )
}

@Composable
private fun ClassicCourseGeneratorResultView(result: ClassicCourseGeneratorResult) {
    SelectionContainer {
        Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
            Text(
                text = "Points: ${result.pointSummary}",
                color = DesktopPalette.Black,
                fontSize = 13.sp,
                fontWeight = FontWeight.Bold
            )
            Text(
                text = when {
                    result.missingElevationPointCount == 0 && result.elevationResolvedPointCount > 0 ->
                        "Elevation: filled ${result.elevationResolvedPointCount} missing point elevations from the local cache."
                    result.missingElevationPointCount == 0 ->
                        "Elevation: complete point elevations available."
                    result.elevationResolvedPointCount > 0 ->
                        "Elevation: filled ${result.elevationResolvedPointCount} missing point elevations from the local cache; ${result.missingElevationPointCount} point elevations remain missing."
                    else ->
                        "Elevation: ${result.missingElevationPointCount} point elevations missing; climb, effective length, and category matching are unavailable."
                },
                color = DesktopPalette.Black,
                fontSize = 13.sp
            )
            if (result.requirementWarnings.isNotEmpty()) {
                Text(
                    text = "Course requirement warnings",
                    color = DesktopPalette.Error,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold
                )
                result.requirementWarnings.forEach { warning ->
                    Text(
                        text = "${warning.label}: ${warning.message}",
                        color = DesktopPalette.Error,
                        fontSize = 13.sp
                    )
                }
            }
            if (result.recommendedCourseSets.isNotEmpty()) {
                Text(
                    text = "Recommended ${result.formatLabel} course sets",
                    color = DesktopPalette.Black,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold
                )
                result.recommendedCourseSets.forEach { set ->
                    Text(
                        text = "Set #${set.index}",
                        color = DesktopPalette.Black,
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold
                    )
                    set.rows.forEach { row ->
                        Text(
                            text = "  ${kilometersText(row.effectiveLengthMeters.roundToInt())} : ${row.orderLabels.joinToString(" -> ")} ${row.routeGeneratorParentheticalText()}",
                            color = Color(0xFF0B5D1E),
                            fontSize = 13.sp
                        )
                    }
                }
            }
            result.groups.forEach { group ->
                Text(
                    text = group.title,
                    color = DesktopPalette.Black,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold
                )
                Text(
                    text = "IDEAL EL : Course Order",
                    color = DesktopPalette.Black,
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Bold
                )
                group.rows.forEach { row ->
                    Text(
                        text = "${kilometersText(row.effectiveLengthMeters.roundToInt())} : ${row.orderLabels.joinToString(" -> ")} ${row.routeGeneratorParentheticalText()}",
                        color = if (row.hasCategoryMatch) Color(0xFF0B5D1E) else Color(0xFF777777),
                        fontSize = 13.sp
                    )
                }
            }
        }
    }
}

