    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        Text(
            text = "Section summary",
            color = DesktopPalette.Black,
            fontSize = 15.sp,
            fontWeight = FontWeight.Bold
        )
        rows.forEach { row ->
            CourseAnalysisRow(row.label, row.value)
        }
