@Composable
private fun CourseAnalysisDetailRows(result: DesktopCourseAnalysisSummary) {
    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        CourseAnalysisRow("Routes compared", result.calculatedRouteCount.toString())
        if (result.idealOrderMatches == true) {
            CourseAnalysisRow("Saved route", result.providedIdealOrder.joinToString(" -> ").ifBlank { "Unknown" })
            CourseAnalysisRow("Order comparison", "Saved and calculated routes match")
        } else {
            CourseAnalysisRow("Calculated ideal route (calculated fox numbering)", result.calculatedIdealOrder.joinToString(" -> ").ifBlank { "Unknown" })
            CourseAnalysisRow("Saved route", result.providedIdealOrder.joinToString(" -> ").ifBlank { "Unknown" })
            CourseAnalysisRow(
                "Order comparison",
                when (result.idealOrderMatches) {
                    true -> "Agrees"
                    false -> "Differs"
                    null -> "Unknown"
                }
            )
            CourseAnalysisRow("Calculated horizontal length", kilometersText(result.calculatedRouteSection?.routeLengthMeters))
        }
        CourseAnalysisRow("Horizontal length", kilometersText(result.routeLengthMeters))
        CourseAnalysisRow("Climb", climbText(result.climbMeters))
        CourseAnalysisRow("Effective length", kilometersText(result.effectiveLengthMeters))
        CourseAnalysisRow("Assumed running speed", courseAnalysisSpeedModelText(result.speedModel))
        CourseAnalysisRow("Estimated ideal time", secondsText(result.estimatedIdealSeconds))
    }
}

@Composable
private fun CourseAnalysisLegRows(title: String, legs: List<DesktopCourseLegRow>) {
    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        Text(
            text = title,
            color = DesktopPalette.Black,
            fontSize = 15.sp,
            fontWeight = FontWeight.Bold
        )
        if (legs.isEmpty()) {
            Text(
                text = "No leg rows available.",
                color = DesktopPalette.Black,
                fontSize = 13.sp
            )
            return@Column
        }
        legs.forEach { leg ->
            val speedText = leg.speedFactorOverride
                ?.let { " (speed x${twoDecimalText(it)})" }
