internal fun readoutSiNumberDisplayText(siNumberText: String, isRentedSiCard: Boolean): String {
    val displayNumber = siNumberText.ifBlank { "-" }
    return if (isRentedSiCard) "Rented SI # $displayNumber" else "SI # $displayNumber"
}

