private fun appendPublicControlLabel(controlPointsText: String, publicLabel: String): String {
    val token = pickerControlToken(publicLabel)
    val existingText = controlPointsText.trim()
    return if (existingText.isEmpty()) token else "$existingText $token"
}

private fun defaultNewPunchElapsedTime(startSeconds: String): String =
    startSeconds.trim().takeIf { it.toReadoutElapsedSecondsOrNull() != null } ?: "00:00"

private fun readoutTimeValidationMessage(
    startElapsed: String,
    finishElapsed: String,
    startSiTime: String,
    finishSiTime: String,
    validateStartElapsed: Boolean
): String? {
    if (startSiTime.isInvalidOptionalReadoutTime()) {
        return "Start SI Time must use mm:ss or hh:mm:ss under 24 hours."
    }
    if (finishSiTime.isInvalidOptionalReadoutTime()) {
        return "Finish SI Time must use mm:ss or hh:mm:ss under 24 hours."
    }
    if (validateStartElapsed && startElapsed.isInvalidOptionalReadoutTime()) {
        return "Start Elapsed must use mm:ss or hh:mm:ss under 24 hours."
    }
    if (finishElapsed.isInvalidFinishElapsedTime(startElapsed, validateStartElapsed)) {
        return "Finish Elapsed must be a valid time and cannot be earlier than Start Elapsed."
    }
    return null
}

private fun readoutEditIssueExplanation(
    resultId: String,
    elapsedBaseSeconds: Long?,
    originalIssueExplanation: String?,
    startElapsed: String,
    finishElapsed: String,
    startSiTime: String,
    finishSiTime: String,
    controlPunches: List<DesktopReadoutPunchEditDraft>,
    resultStatus: ResultStatus
): String? {
    val startSeconds = startSiTime.toReadoutElapsedSecondsOrNull()
        ?: startElapsed.toReadoutDaySecondsOrNull(elapsedBaseSeconds)
    val finishSeconds = finishSiTime.toReadoutElapsedSecondsOrNull()
        ?: finishElapsed.toReadoutDaySecondsOrNull(elapsedBaseSeconds)
    val punches = controlPunches.mapIndexed { index, punch ->
        val siTimeSeconds = punch.siTime.toReadoutElapsedSecondsOrNull() ?: return null
        EventAliasPunch(
            punch = EventPunch(
                id = punch.rowId,
                raceId = "",
                resultId = resultId,
                cardNumber = null,
                siCode = punch.siCode,
                siTimeSeconds = siTimeSeconds,
                originalSiTimeSeconds = siTimeSeconds,
                punchType = SIRecordType.CONTROL,
                order = index,
                punchStatus = punch.punchStatus,
                splitSeconds = 0
            ),
            alias = null
        )
    }
    val statusForExplanation = if (
        resultStatus == ResultStatus.ERROR &&
        originalIssueExplanation != "The result status is set to Error manually."
    ) {
        ResultStatus.OK
    } else {
        resultStatus
    }
    return EventReadoutData(
        result = EventResult(
            id = resultId,
            raceId = "",
            competitorId = null,
            siNumber = null,
            cardType = 0.toByte(),
            checkTimeSeconds = null,
            startTimeSeconds = startSeconds,
            finishTimeSeconds = finishSeconds,
            readoutDateTimeIso = "",
            automaticStatus = false,
            resultStatus = statusForExplanation,
            points = 0,
            runTimeSeconds = 0,
            modified = true,
            sent = false
        ),
        punches = punches
    ).readoutIssueExplanation()
}

private fun String.isInvalidOptionalReadoutTime(): Boolean =
    isNotBlank() && toReadoutElapsedSecondsOrNull() == null

private fun String.isInvalidRequiredReadoutTime(): Boolean =
    isBlank() || toReadoutElapsedSecondsOrNull() == null

private fun String.isInvalidFinishElapsedTime(startElapsed: String, validateStartElapsed: Boolean): Boolean {
    if (isInvalidOptionalReadoutTime()) {
        return true
    }
    val finishSeconds = toReadoutElapsedSecondsOrNull() ?: return false
    val startSeconds = if (validateStartElapsed) {
        startElapsed.toReadoutElapsedSecondsOrNull()
    } else {
        null
    }
    return startSeconds != null && finishSeconds < startSeconds
}

private fun List<DesktopReadoutPunchEditDraft>.validationMessage(timeMode: DesktopReadoutPunchTimeMode): String? =
    mapIndexedNotNull { index, punch ->
        val label = "Punch ${index + 1}"
        val timeText = punch.timeText(timeMode)
        when {
            timeText.isInvalidRequiredReadoutTime() -> "$label ${timeMode.columnLabel.lowercase()} must use mm:ss or hh:mm:ss under 24 hours."
            else -> null
        }
    }.firstOrNull()

private fun DesktopReadoutPunchEditDraft.timeText(timeMode: DesktopReadoutPunchTimeMode): String =
    when (timeMode) {
        DesktopReadoutPunchTimeMode.ELAPSED -> elapsedTime
        DesktopReadoutPunchTimeMode.SI -> siTime
    }

private fun DesktopReadoutPunchEditDraft.withEditedTime(
    timeMode: DesktopReadoutPunchTimeMode,
    value: String,
    elapsedBaseSeconds: Long?
): DesktopReadoutPunchEditDraft =
    when (timeMode) {
        DesktopReadoutPunchTimeMode.ELAPSED -> {
            val siTime = value.toReadoutSiTimeText(elapsedBaseSeconds)
            copy(
                elapsedTime = value,
                siTime = siTime ?: this.siTime
            )
        }
        DesktopReadoutPunchTimeMode.SI -> {
            val elapsedTime = value.toReadoutElapsedText(elapsedBaseSeconds)
            copy(
                siTime = value,
                elapsedTime = elapsedTime ?: this.elapsedTime
            )
        }
    }

private fun String.toReadoutSiTimeText(elapsedBaseSeconds: Long?): String? =
    toReadoutElapsedSecondsOrNull()
        ?.let { elapsedSeconds -> (elapsedBaseSeconds ?: 0L) + elapsedSeconds }
        ?.toReadoutSiTimeText()

private fun String.toReadoutElapsedText(elapsedBaseSeconds: Long?): String? =
    toReadoutElapsedSecondsOrNull()
        ?.let { siSeconds ->
            if (elapsedBaseSeconds == null) {
                siSeconds
            } else {
                (siSeconds - elapsedBaseSeconds).toSportIdentDaySeconds()
            }
        }
        ?.toReadoutElapsedText()

private fun String.toReadoutDaySecondsOrNull(elapsedBaseSeconds: Long?): Long? =
    toReadoutElapsedSecondsOrNull()
        ?.let { elapsedSeconds -> ((elapsedBaseSeconds ?: 0L) + elapsedSeconds).toSportIdentDaySeconds() }

private fun String.toReadoutElapsedSecondsOrNull(): Long? {
    val parts = trim().split(":")
    if (parts.size != 2 && parts.size != 3) {
        return null
    }
    val hours = if (parts.size == 3) parts[0].toLongOrNull() ?: return null else 0L
    val minutes = parts[if (parts.size == 3) 1 else 0].toLongOrNull() ?: return null
    val seconds = parts[if (parts.size == 3) 2 else 1].toLongOrNull() ?: return null
    if (hours < 0 || minutes !in 0..59 || seconds !in 0..59) {
        return null
    }
    val totalSeconds = hours * 3_600 + minutes * 60 + seconds
    return totalSeconds.takeIf { it in 0 until SportIdentCodes.SECONDS_DAY }
}

private fun <T> List<T>.moved(fromIndex: Int, toIndex: Int): List<T> {
    if (fromIndex !in indices || toIndex !in indices || fromIndex == toIndex) {
        return this
    }
    val mutableRows = toMutableList()
    val row = mutableRows.removeAt(fromIndex)
    mutableRows.add(toIndex, row)
    return mutableRows
}

private fun EventControl.editPunchToken(allControls: List<EventControl>): String {
    val publicLabel = publicDisplayLabel()
    val publicLabelKey = publicLabel.normalizedReadoutControlToken()
    val isAmbiguous = allControls
        .filter { control -> publicLabelKey in control.entryKeys() }
        .map { it.siCode }
        .distinct()
        .size > 1
    return if (isAmbiguous) siCode.toString() else publicLabel
}

private fun DesktopReadoutPunchEditDraft.controlIdentityKeys(): Set<String> =
    buildSet {
        controlId?.let { add("id:$it") }
        add("si:$siCode")
        controlText
            .takeIf { it.isNotBlank() }
            ?.normalizedReadoutControlToken()
            ?.let { add("token:$it") }
    }

private fun EventControl.controlIdentityKeys(): Set<String> =
    buildSet {
        add("id:$id")
        add("si:$siCode")
        entryKeys().forEach { add("token:$it") }
    }

private fun EventControl.entryKeys(): Set<String> =
    buildSet {
        add(siCode.toString().normalizedReadoutControlToken())
        add(label.normalizedReadoutControlToken())
        add(publicDisplayLabel().normalizedReadoutControlToken())
        publicLabel?.takeIf { it.isNotBlank() }?.let { add(it.normalizedReadoutControlToken()) }
    }

private fun String.normalizedReadoutControlToken(): String =
    trim().lowercase().replace(Regex("\\s+"), " ")

private fun selectedPublicControlLabels(
    controlPointsText: String,
    controls: List<EventControlDetails>
): Set<String> {
    val uniqueControlsByPublicLabel = controls
        .filter { isPickerSafePublicLabel(it.publicDisplayLabel()) }
        .groupBy { it.publicDisplayLabel() }
        .filterValues { controlsForLabel -> controlsForLabel.size == 1 }
        .mapValues { (_, controlsForLabel) -> controlsForLabel.single() }
    return ControlPointRules.tokenizeControlPoints(controlPointsText)
        .mapNotNull { token -> uniqueControlsByPublicLabel[token.trim()]?.publicDisplayLabel() }
        .toSet()
}

private fun selectedProtectedIdealOrderControlIds(
    idealOrderText: String,
    controls: List<EventControl>
): Set<String> =
    runCatching {
        ProtectedIdealOrderRules.resolveControlIds(idealOrderText, controls).toSet()
    }.getOrDefault(emptySet())

private fun EventProjectFile.categoryHasLockedProtectedCourseData(
    categoryId: String,
    isProtectedCourseOrderUnlocked: Boolean
): Boolean =
    !isProtectedCourseOrderUnlocked &&
        raceData.categories.any {
            it.category.id == categoryId &&
                (it.category.encryptedIdealOrder?.isNotBlank() == true ||
                    it.category.encryptedCourseInfo?.isNotBlank() == true)
        }

private fun EventProjectFile.lockedProtectedCourseWarning(isProtectedCourseOrderUnlocked: Boolean): String =
    if (hasLockedProtectedCourseData(isProtectedCourseOrderUnlocked)) {
        " Course data is locked; unlock it to run full protected-route safety checks."
    } else {
        ""
    }

private fun EventProjectFile.lockedCategoryCourseWarning(
    categoryId: String,
    isProtectedCourseOrderUnlocked: Boolean
): String =
    if (categoryHasLockedProtectedCourseData(categoryId, isProtectedCourseOrderUnlocked)) {
        " This category has locked protected course data; unlock it to compare stored route data."
    } else {
        ""
    }

private fun EventProjectFile.hasRecordedReadoutsOrResults(): Boolean =
    raceData.competitorData.any { it.readoutData != null } || raceData.unmatchedReadoutData.isNotEmpty()

private fun EventProjectFile.resultImpactWarning(action: String): String =
    if (hasRecordedReadoutsOrResults()) {
        " $action after readouts exist; review or recalculate affected results."
    } else {
        ""
    }

private fun raceOpsPreflightWarning(
    projectFile: EventProjectFile,
    protectedCourseInfoByCategoryId: Map<String, ProtectedCourseInfo>,
    isProtectedCourseOrderUnlocked: Boolean
): String? {
    val activeIssues = DesktopProjectDiagnostics.from(projectFile, protectedCourseInfoByCategoryId)
        .readinessIssues
        .filterNot { it.contains("has course data but no competitors") }
        .toMutableList()
    if (projectFile.hasLockedProtectedCourseData(isProtectedCourseOrderUnlocked)) {
        activeIssues += "Course data is locked; unlock it to run full protected-route safety checks."
    }
    return activeIssues
        .takeIf { it.isNotEmpty() }
        ?.let { issues ->
            val suffix = if (issues.size > 1) " ${issues.size - 1} more readiness issues." else ""
            "Readiness warning: ${issues.first()}$suffix"
        }
}

private fun protectedControlLocationSummaries(
    projectFile: EventProjectFile,
    protectedCourseInfoByCategoryId: Map<String, ProtectedCourseInfo>
): List<ProtectedControlLocationSummary> {
    val protectedControlPointsById = protectedCourseInfoByCategoryId.values
        .flatMap { it.controlPoints }
        .groupBy { it.controlId }
    val affectedCategoryCounts = projectFile.raceData.controls.associate { control ->
        control.id to protectedCourseInfoByCategoryId.values.count { courseInfo ->
            courseInfo.controlPoints.any { it.controlId == control.id } ||
                courseInfo.courseObjects.any { it.id == control.id }
        }
    }
    return projectFile.raceData.controls
        .sortedWith(compareBy<EventControl> { it.siCode }.thenBy { it.publicDisplayLabel() })
        .map { control ->
            val protectedPoint = protectedControlPointsById[control.id]?.firstOrNull()
            ProtectedControlLocationSummary(
                controlId = control.id,
                label = control.publicDisplayLabel().ifBlank { control.siCode.toString() },
                latitude = protectedPoint?.latitude,
                longitude = protectedPoint?.longitude,
                affectedCategoryCount = affectedCategoryCounts[control.id] ?: 0
            )
        }
}

private fun EventControlDetails.publicDisplayLabel(): String =
    publicLabel.trim().ifEmpty { label }

private fun EventControl.publicDisplayLabel(): String =
