@Composable
private fun LabeledTextField(
    label: String,
    value: String,
    onValueChange: (String) -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    placeholder: String = "",
    isError: Boolean = false,
    onCommit: (() -> Unit)? = null
) {
    Column(verticalArrangement = Arrangement.spacedBy(4.dp), modifier = modifier) {
        Text(
            text = label,
            color = when {
                !enabled -> DesktopPalette.Disconnected
                isError -> DesktopPalette.Error
                else -> DesktopPalette.Black
            },
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold
        )
        TextField(
            value = value,
            onValueChange = onValueChange,
            singleLine = true,
            placeholder = placeholder.takeIf { it.isNotBlank() }?.let { placeholderText ->
                { Text(placeholderText) }
            },
            modifier = Modifier
                .fillMaxWidth()
                .then(if (onCommit != null) Modifier.commitOnEnter(onCommit) else Modifier),
            enabled = enabled,
            isError = isError
        )
    }
}

